import spidev
from gpiozero import MCP3208
from Adafruit_GPIO import SPI
import paho.mqtt.client as mqtt
import time

# gpiozero function
def read_mcp3208_gpiozero(channel):
    try:
        if channel < 0 or channel > 7:
            return -1
        adc = MCP3208(channel)
        return adc.value
    except Exception as e:
        print(f"Error in gpiozero function: {e}")
        return -1

# spidev function
def read_mcp3208_spidev(channel):
    try:
        if channel < 0 or channel > 7:
            return -1
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = 1000000
        spi.mode = 0
        spi.lsbfirst = False
        cmd = 0b00001100 | (channel & 0x07) << 2
        data = spi.xfer2([cmd, 0x00, 0x00])
        spi.close()
        return ((data[1] & 0x0F) << 8) | data[2]
    except Exception as e:
        print(f"Error in spidev function: {e}")
        return -1

# Adafruit_GPIO function
def read_mcp3208_adafruit(channel):
    try:
        if channel < 0 or channel > 7:
            return -1
        spi = SPI.SpiDev(0, 0, max_speed_hz=1000000, mode=0, msbfirst=True)
        cmd = 0b00001100 | (channel & 0x07) << 2
        data = spi.xfer2([cmd, 0x00, 0x00])
        return ((data[1] & 0x0F) << 8) | data[2]
    except Exception as e:
        print(f"Error in Adafruit_GPIO function: {e}")
        return -1

def main():
    channel = 0
    gpiozero_result = read_mcp3208_gpiozero(channel)
    spidev_result = read_mcp3208_spidev(channel)
    adafruit_result = read_mcp3208_adafruit(channel)

    if gpiozero_result == -1:
        print("Error: gpiozero function failed.")
    else:
        print(f"gpiozero result: {gpiozero_result}")

    if spidev_result == -1:
        print("Error: spidev function failed.")
    else:
        print(f"spidev result: {spidev_result}")

    if adafruit_result == -1:
        print("Error: Adafruit_GPIO function failed.")
    else:
        print(f"Adafruit_GPIO result: {adafruit_result}")

if __name__ == "__main__":
    main()

