import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except (OSError, IOError) as e:
            print(f"Failed to open SPI device: {e}")
            sys.exit(1)

    def send_spi_command(self, data):
        try:
            return self.spi.xfer2(data)
        except (OSError, IOError) as e:
            print(f"Failed to transfer data over SPI: {e}")
            return None

    def extract_10bit(self, response):
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        response = self.send_spi_command([0x01, 0x80, 0x00])
        if response is not None:
            return self.extract_10bit(response)
        return None

    def convert_to_weight(self, raw_data):
        if raw_data is not None:
            return float(raw_data) * (5.0 / 1023.0)
        return None

    def close(self):
        self.spi.close()
        print("SPI device closed.")

def signal_handler(sig, frame):
    print("Received termination signal. Shutting down...")
    sys.exit(0)

def main():
    signal.signal(signal.SIGTERM, signal_handler)
    load_cell_reader = LoadCellReader()

    try:
        while True:
            raw_data = load_cell_reader.read_raw_data()
            weight = load_cell_reader.convert_to_weight(raw_data)
            if weight is not None:
                print(f'Weight: {weight:.2f} kg')
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Keyboard interrupt received. Shutting down...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        load_cell_reader.close()

if __name__ == "__main__":
    main()

