    handlers=[
        logging.FileHandler("occupancy_lights.log"),
        logging.StreamHandler()
    ]
)

# Set up GPIO mode
GPIO.setmode(GPIO.BCM)

# MotionSensor class
class MotionSensor:
    def __init__(self, pin, sampling_period=1.0, threshold=2):
        self.pin = pin
        self.sampling_period = sampling_period
        self.threshold = threshold
        self.count = 0
        self.lock = threading.Lock()
        self.setup()

    def setup(self):
        if not GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN):
            logging.error(f"Failed to set up GPIO {self.pin}")
            return
        GPIO.add_event_detect(self.pin, GPIO.RISING, callback=self.callback, bouncetime=200)

    def callback(self, channel):
        with self.lock:
            self.count += 1
            logging.debug(f"Motion detected on pin {self.pin}. Count: {self.count}")

    def check_threshold(self):
        with self.lock:
            if self.count >= self.threshold:
                self.count = 0
                return True
            return False

    def reset(self):
        with self.lock:
            self.count = 0

# LightingController class
class LightingController:
    def __init__(self, led_pin, light_sensor, debug_mode=False):
        self.led_pin = led_pin
        self.light_sensor = light_sensor
        self.debug_mode = debug_mode
        self.led_on = False
        self.timer = None
        self.off_delay = 300
        self.setup()

    def setup(self):
        if not GPIO.setup(self.led_pin, GPIO.OUT):
            logging.error(f"Failed to set up GPIO {self.led_pin}")
            return
        self.turn_off()

    def turn_on(self):
        if not self.led_on:
            GPIO.output(self.led_pin, GPIO.HIGH)
            self.led_on = True
            logging.info("LED turned ON")
            if self.timer:
                self.timer.cancel()
            self.timer = threading.Timer(self.off_delay, self.turn_off)
            self.timer.start()

    def turn_off(self):
        if self.led_on:
            GPIO.output(self.led_pin, GPIO.LOW)
            self.led_on = False
            logging.info("LED turned OFF")

    def read_light_level(self):
        try:
            return self.light_sensor.read_light_level()
        except Exception as e:
            logging.error(f"Error reading light level: {e}")
            return 0

# Simulated light sensor
class SimulatedLightSensor:
    def read_light_level(self):
        return 75  # Simulated light level

# Main function
def main():
    try:
        motion_sensor1 = MotionSensor(pin=17)
        motion_sensor2 = MotionSensor(pin=27)
        light_sensor = SimulatedLightSensor()
        lighting_controller = LightingController(led_pin=22, light_sensor=light_sensor, debug_mode=True)

        def main_loop():
            while True:
                if motion_sensor1.check_threshold() or motion_sensor2.check_threshold():
                    light_level = lighting_controller.read_light_level()
                    if light_level > 60:
                        lighting_controller.turn_on()
                time.sleep(motion_sensor1.sampling_period)

        main_thread = threading.Thread(target=main_loop)
        main_thread.start()
        main_thread.join()

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed")

if __name__ == "__main__":
    atexit.register(GPIO.cleanup)
    main()

