import spidev
import numpy as np
import csv
import logging
import signal
import time
from datetime import datetime

class SoilMoistureSensor:
    def __init__(self, bus=0, device=0, max_speed_hz=1200000, dry=820, wet=400):
        self.bus = bus
        self.device = device
        self.max_speed_hz = max_speed_hz
        self.dry = dry
        self.wet = wet
        self.spi = None
        self.open_spi()
        self.history = []

    def open_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.bus, self.device)
            self.spi.max_speed_hz = self.max_speed_hz
            logging.info("SPI device opened successfully.")
        except Exception as e:
            logging.error(f"Failed to open SPI device: {e}")
            raise

    def read_adc(self, channel):
        if self.spi is None:
            raise RuntimeError("SPI device not initialized.")
        try:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"Failed to read from ADC: {e}")
            return None

    def compute_moisture_percentage(self, raw_value):
        if raw_value is None:
            return None
        try:
            percentage = 100 * ((self.dry - raw_value) / (self.dry - self.wet))
            return max(0, min(100, percentage))
        except ZeroDivisionError:
            logging.error("Dry and wet calibration values are the same.")
            return None

    def update_history(self, percentage):
        if percentage is not None:
            self.history.append(percentage)
            if len(self.history) > 25:
                self.history.pop(0)

    def compute_statistics(self):
        if not self.history:
            return None, None
        mean = np.mean(self.history)
        std_dev = np.std(self.history)
        return mean, std_dev

    def log_reading(self, percentage):
        timestamp = datetime.now().isoformat()
        with open('soil_moisture_log.csv', mode='a', newline='') as file:
            writer = csv.writer(file)
            writer.writerow([timestamp, percentage])

    def close_spi(self):
        if self.spi is not None:
            self.spi.close()
            logging.info("SPI device closed.")

def signal_handler(sig, frame):
    logging.info("Received exit signal. Cleaning up...")
    sensor.close_spi()
    exit(0)

def main():
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    global sensor
    sensor = SoilMoistureSensor()

    try:
        for _ in range(25):
            raw_value = sensor.read_adc(channel=2)
            if raw_value is not None and raw_value not in [0, 1023]:
                moisture_percentage = sensor.compute_moisture_percentage(raw_value)
                sensor.update_history(moisture_percentage)
                sensor.log_reading(moisture_percentage)
                mean, std_dev = sensor.compute_statistics()
                logging.info(f"Moisture: {moisture_percentage:.2f}%, Mean: {mean:.2f}%, Std Dev: {std_dev:.2f}%")
            else:
                logging.warning("Sensor reading is invalid or out of expected range.")
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received. Exiting...")
    finally:
        sensor.close_spi()

if __name__ == "__main__":
    main()

