class BalanceBeamController:
    def __init__(self):
        # Initialize GPIO factory
        self.factory = PiGPIOFactory()

        # Initialize distance sensor
        self.sensor = DistanceSensor(echo=24, trigger=23, max_distance=1, pin_factory=self.factory)

        # Initialize servo
        self.servo = AngularServo(25, initial_angle=0, min_angle=0, max_angle=50, pin_factory=self.factory)

        # Initialize PID controller
        self.pid = PID(0.5, 0.00, 0.4, setpoint=25)
        self.pid.output_limits = (0, 50)

        # Control loop variables
        self.balance_time = 0
        self.balance_threshold = 3
        self.max_error = 25
        self.running = True

    def run(self):
        try:
            while self.running:
                try:
                    distance = self.sensor.distance * 100  # Convert to cm
                except Exception as e:
                    logging.error(f"Sensor read error: {e}")
                    time.sleep(0.1)
                    continue

                logging.info(f"Sensor reading: {distance:.2f} cm")

                error = self.pid(setpoint=self.pid.setpoint, process_variable=distance)

                if abs(error) > self.max_error:
                    logging.warning(f"Error exceeds max threshold: {error:.2f} cm")
                else:
                    try:
                        self.servo.angle = error
                        logging.info(f"Servo command: {error:.2f} degrees")
                    except Exception as e:
                        logging.error(f"Servo write error: {e}")

                if abs(distance - self.pid.setpoint) <= self.balance_threshold:
                    self.balance_time += 1
                    if self.balance_time >= 3:
                        logging.info("Balance achieved. Detaching servo.")
                        self.servo.detach()
                        self.running = False
                else:
                    self.balance_time = 0

                time.sleep(0.1)

        except KeyboardInterrupt:
            logging.info("Received SIGINT. Stopping control loop.")
        finally:
            self.cleanup()

    def cleanup(self):
        try:
            self.servo.detach()
        except Exception as e:
            logging.error(f"Error detaching servo: {e}")

        try:
            self.sensor.close()
        except Exception as e:
            logging.error(f"Error closing sensor: {e}")

        try:
            self.factory.close()
        except Exception as e:
            logging.error(f"Error closing GPIO factory: {e}")

def main():
    controller = BalanceBeamController()
    controller.run()

if __name__ == "__main__":
