import cv2
import signal
import sys
import time
from gpiozero import LED, Button, AngularServo
from picamera2 import Picamera2, Preview
from pathlib import Path

# GPIO setup
try:
    led = LED(14)
    button = Button(15, pull_up=True)
    servo = AngularServo(18, min_angle=0, max_angle=180, min_pulse_width=0.002, max_pulse_width=0.012, frequency=50)
except Exception as e:
    print(f"GPIO initialization failed: {e}")
    led = None
    button = None
    servo = None

# Load the cascade classifier
cascade_path = Path("/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml")
if not cascade_path.is_file():
    raise FileNotFoundError(f"Cascade classifier not found at {cascade_path}")

face_cascade = cv2.CascadeClassifier(str(cascade_path))
if face_cascade.empty():
    raise RuntimeError("Failed to load cascade classifier")

# Initialize camera
try:
    picam2 = Picamera2()
    picam2.configure(picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (320, 240)}))
    picam2.start()
except Exception as e:
    print(f"Camera initialization failed: {e}")
    picam2 = None

# Global variables
current_angle = 90
gui_enabled = True

def cleanup(signum, frame):
    global gui_enabled
    print("\nCleaning up...")
    if picam2:
        picam2.stop()
    if led:
        led.off()
    if servo:
        servo.detach()
    cv2.destroyAllWindows()
    sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

def process_frame(frame):
    global current_angle
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

    if len(faces) > 0:
        led.on() if led else None
        for (x, y, w, h) in faces:
            face_center_x = x + w // 2
            if face_center_x < frame.shape[1] // 2:
                current_angle = max(0, current_angle - 20)
            else:
                current_angle = min(180, current_angle + 20)
            if servo:
                servo.angle = current_angle
            time.sleep(0.02)
            cv2.rectangle(frame, (x, y), (x+w, y+h), (255, 0, 0), 2)
    else:
        led.off() if led else None

    if gui_enabled:
        try:
            cv2.imshow('Human Detection', frame)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                cleanup(None, None)
        except Exception as e:
            print(f"GUI display failed: {e}")
            global gui_enabled
            gui_enabled = False

try:
    while True:
        if picam2:
            frame = picam2.capture_array()
            process_frame(frame)
        else:
            print("Camera not available. Skipping frame processing.")
            time.sleep(1)
except KeyboardInterrupt:
    cleanup(None, None)

import spidev
import RPi.GPIO as GPIO
import time
import logging
from datetime import datetime
import os

# Constants
SPI_BUS = 0
SPI_DEVICE = 0
CHANNELS = [0, 1]
VREF = 3.3
SENSITIVITY = 0.1
RELAY_PIN = 17
SAMPLE_INTERVAL = 5
LOG_FILE = 'greenhouse_energy_log.csv'
ERROR_LOG_FILE = 'greenhouse_energy_monitoring.log'
HEADER = "Timestamp,Primary Current (A),Secondary Current (A),Primary Power (W),Secondary Power (W)\n"

# Setup logging
logging.basicConfig(filename=ERROR_LOG_FILE, level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def setup_spi():
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = 1000000  # 1 MHz
        return spi
    except Exception as e:
        logging.error(f"Failed to setup SPI: {e}")
        raise

def read_adc(spi, channel):
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        voltage = (data * VREF) / 1023.0
        return voltage
    except Exception as e:
        logging.error(f"Failed to read ADC channel {channel}: {e}")
        return None

def compute_current(voltage):
    if voltage is None:
        return None
    return (voltage - VREF / 2) / SENSITIVITY

def compute_power(current):
    if current is None:
        return None
    return current * 230

def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT)
    except Exception as e:
        logging.error(f"Failed to setup GPIO: {e}")
        raise

def cleanup_gpio():
    GPIO.cleanup()

def cleanup_spi(spi):
    spi.close()

def log_data(timestamp, primary_current, secondary_current, primary_power, secondary_power):
    try:
        file_exists = os.path.isfile(LOG_FILE)
        with open(LOG_FILE, 'a') as f:
            if not file_exists:
                f.write(HEADER)
            f.write(f"{timestamp},{primary_current:.2f},{secondary_current:.2f},{primary_power:.2f},{secondary_power:.2f}\n")
    except Exception as e:
        logging.error(f"Failed to log data: {e}")

def main():
    spi = None
    try:
        spi = setup_spi()
        setup_gpio()

        if not os.path.isfile(LOG_FILE):
            with open(LOG_FILE, 'w') as f:
                f.write(HEADER)

        while True:
            try:
                primary_voltage = read_adc(spi, CHANNELS[0])
                secondary_voltage = read_adc(spi, CHANNELS[1])

                primary_current = compute_current(primary_voltage)
                secondary_current = compute_current(secondary_voltage)

                primary_power = compute_power(primary_current)
                secondary_power = compute_power(secondary_current)

                timestamp = datetime.now().isoformat()
                log_data(timestamp, primary_current, secondary_current, primary_power, secondary_power)

                if primary_power is not None and primary_power > 1000:
                    GPIO.output(RELAY_PIN, GPIO.HIGH)
                else:
                    GPIO.output(RELAY_PIN, GPIO.LOW)

            except Exception as e:
                logging.error(f"Error during sampling: {e}")

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        logging.info("Script interrupted by user.")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if spi:
            cleanup_spi(spi)
        cleanup_gpio()

if __name__ == "__main__":
    main()

