import RPi.GPIO as GPIO
import picamera2
import csv
import time
import os
import argparse
from datetime import datetime
import signal
import sys

def setup_gpio(pins):
    GPIO.setmode(GPIO.BCM)
    for pin in pins:
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    return {pin: [] for pin in pins}

def calibrate_sensors(pins, interval, duration):
    end_time = time.time() + duration
    baseline_readings = {pin: [] for pin in pins}

    while time.time() < end_time:
        for pin in pins:
            baseline_readings[pin].append(GPIO.input(pin))
        time.sleep(interval)

    thresholds = {}
    for pin, readings in baseline_readings.items():
        high_count = sum(readings)
        baseline_percentage = (high_count / len(readings)) * 100
        thresholds[pin] = baseline_percentage + 20

    return thresholds

def monitor_sensors(pins, thresholds, interval, log_file, picture_interval):
    try:
        with open(log_file, 'w', newline='') as csvfile:
            log_writer = csv.writer(csvfile)
            log_writer.writerow(['Timestamp', 'Sensor1', 'Sensor2', 'Sensor3'])

            camera = picamera2.Picamera2()
            try:
                camera.configure(camera.create_preview_configuration(main={"size": (640, 480)}))
                camera.start()
            except Exception as e:
                print(f"Camera initialization failed: {e}")
                camera = None

            last_picture_time = time.time()
            try:
                while True:
                    current_time = time.time()
                    sensor_states = {pin: GPIO.input(pin) for pin in pins}
                    active_states = {pin: 1 if (sum(sensor_states[pin] for _ in range(5)) / 5) > thresholds[pin] else 0 for pin in pins}

                    timestamp = datetime.now().isoformat()
                    log_writer.writerow([timestamp, active_states[pins[0]], active_states[pins[1]], active_states[pins[2]]])
                    csvfile.flush()

                    if camera and (current_time - last_picture_time) >= picture_interval:
                        image_filename = f"images/{timestamp.replace(':', '-')}.jpg"
                        os.makedirs(os.path.dirname(image_filename), exist_ok=True)
                        camera.capture_file(image_filename)
                        last_picture_time = current_time

                    time.sleep(interval)
            except KeyboardInterrupt:
                print("Monitoring interrupted by user.")
            finally:
                if camera:
                    camera.stop()
                    camera.close()
    except IOError:
        print("Failed to open log file. Falling back to console logging.")
        while True:
            sensor_states = {pin: GPIO.input(pin) for pin in pins}
            active_states = {pin: 1 if (sum(sensor_states[pin] for _ in range(5)) / 5) > thresholds[pin] else 0 for pin in pins}
            timestamp = datetime.now().isoformat()
            print(f"{timestamp}, {active_states[pins[0]]}, {active_states[pins[1]]}, {active_states[pins[2]]}")
            time.sleep(interval)

def cleanup(signum, frame):
    print("Cleaning up resources...")
    GPIO.cleanup()
    sys.exit(0)

def main():
    parser = argparse.ArgumentParser(description="Monitor vibration sensors and capture images.")
    parser.add_argument('-g', '--gpio', nargs=3, type=int, required=True, help="Three BCM GPIO pin numbers")
    parser.add_argument('-l', '--log_file', type=str, required=True, help="CSV log file path")
    parser.add_argument('-i', '--interval', type=float, required=True, help="Sampling interval in seconds")
    parser.add_argument('-c', '--calibrate', type=int, required=True, help="Calibration duration in seconds")
    parser.add_argument('-p', '--picture_interval', type=int, required=True, help="Picture capture interval in seconds")
    args = parser.parse_args()

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        sensor_readings = setup_gpio(args.gpio)
        thresholds = calibrate_sensors(args.gpio, args.interval, args.calibrate)
        monitor_sensors(args.gpio, thresholds, args.interval, args.log_file, args.picture_interval)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

