from pyzbar.pyzbar import decode
from PIL import Image
import csv
import os
import time
import re
from datetime import datetime

def is_valid_item_id(item_id):
    return bool(re.match(r'^[A-Za-z0-9]+$', item_id))

def log_to_csv(camera_id, item_id, capture_time):
    try:
        file_exists = os.path.isfile('inventory_log.csv')
        with open('inventory_log.csv', mode='a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            if not file_exists:
                writer.writerow(['camera_id', 'item_id', 'capture_time'])
            writer.writerow([camera_id, item_id, capture_time])
    except Exception as e:
        log_error(f"CSV file I/O error: {e}")

def log_error(message):
    timestamp = datetime.now().isoformat()
    with open('error_log.txt', 'a') as error_log:
        error_log.write(f"{timestamp} - {message}\n")

def main():
    camera_index = 0
    camera = cv2.VideoCapture(camera_index)

    if not camera.isOpened():
        log_error("Camera initialization failure")
        return

    try:
        while True:
            ret, frame = camera.read()
            if not ret:
                log_error("Frame capture failure")
                continue

            gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            decoded_objects = decode(Image.fromarray(gray_frame))

            for obj in decoded_objects:
                item_id = obj.data.decode('utf-8')
                if is_valid_item_id(item_id):
                    capture_time = datetime.now().isoformat()
                    log_to_csv('Camera 1', item_id, capture_time)
                else:
                    log_error(f"Validation failure for item_id: {item_id}")

            time.sleep(0.2)

    except KeyboardInterrupt:
        print("Shutting down gracefully...")
    finally:
        camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

