import io
import signal
import threading
import logging
import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.outputs import FileOutput
from paho.mqtt import client as mqtt_client
import websocket

logging.basicConfig(level=logging.INFO)

class WebSocketHandler:
    def has_connections(self):
        # Stub method to check if there are active WebSocket connections
        pass

    def broadcast(self, data):
        # Stub method to broadcast data over WebSocket
        pass

class CameraStreamBuffer:
    def __init__(self, websocket_handler: WebSocketHandler):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be an instance of WebSocketHandler")
        self.websocket_handler = websocket_handler
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.current_frame = None

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            if data.startswith(b'\xff\xd8'):
                self.flush()

    def flush(self):
        with self.lock:
            if self.buffer.tell() > 0:
                self.current_frame = self.buffer.getvalue()
                self.buffer = io.BytesIO()
                if self.websocket_handler.has_connections():
                    self.websocket_handler.broadcast(self.current_frame)

class MotionDetectionBuffer:
    def __init__(self, detect_motion_function):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.previous_frame = None
        self.current_frame = None

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            if data.startswith(b'\xff\xd8'):
                self.flush()

    def _convert_to_opencv_frame(self, frame_data):
        try:
            nparr = np.frombuffer(frame_data, dtype=np.uint8)
            return cv2.imdecode(nparr, cv2.IMREAD_COLOR)
        except Exception as e:
            logging.error(f"Failed to decode frame: {e}")
            return None

    def flush(self):
        with self.lock:
            if self.buffer.tell() > 0:
                self.current_frame = self.buffer.getvalue()
                self.buffer = io.BytesIO()
                if self.previous_frame is not None:
                    prev_frame = self._convert_to_opencv_frame(self.previous_frame)
                    curr_frame = self._convert_to_opencv_frame(self.current_frame)
                    if prev_frame is not None and curr_frame is not None:
                        self.detect_motion_function(prev_frame, curr_frame)
                self.previous_frame = self.current_frame

def signal_handler(sig, frame, picam2, camera_stream_buffer, motion_detection_buffer):
    logging.info("Shutting down...")
    picam2.stop()
    camera_stream_buffer.flush()
    motion_detection_buffer.flush()

