import time
import smbus2
import signal
import sys

# Constants
I2C_BUS_NUMBER = 1
OLED_ADDRESS = 0x3C
TEMP_FILE_PATH = '/sys/class/thermal/thermal_zone0/temp'

def read_cpu_temperature():
    try:
        with open(TEMP_FILE_PATH, 'r') as temp_file:
            temp_milli = int(temp_file.read().strip())
            return temp_milli / 1000.0
    except FileNotFoundError:
        print("Error: Temperature file not found.")
    except PermissionError:
        print("Error: Permission denied when accessing the temperature file.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    return None

def signal_handler(sig, frame):
    print("\nExiting...")
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS_NUMBER)
        print(f"I2C bus {I2C_BUS_NUMBER} initialized.")

        while True:
            temperature = read_cpu_temperature()
            if temperature is not None:
                print(f"CPU Temperature: {temperature:.2f}°C")
            time.sleep(2)

    except smbus2.error as e:
        print(f"Error initializing I2C bus: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus:
            bus.close()
            print("I2C bus released.")

if __name__ == "__main__":
    main()

import os
import signal
import time
from PIL import Image, ImageOps
from luma.core.interface.serial import spi
from luma.core.render import canvas
from luma.lcd.device import st7789
from luma.core.error import DeviceDisplayModeError
import logging

class GifPlayer:
    def __init__(self, folder_path):
        self.folder_path = folder_path
        self.device = None
        self.gif_files = []
        self._setup_display()
        self._load_gif_files()

    def _setup_display(self):
        try:
            serial = spi(device=0, port=0, bus_speed_hz=8000000)
            self.device = st7789(serial, rotate=0)
        except Exception as e:
            logging.error(f"Failed to initialize display: {e}")
            raise

    def _load_gif_files(self):
        try:
            if not os.path.isdir(self.folder_path):
                raise FileNotFoundError(f"Folder not found: {self.folder_path}")
            self.gif_files = [f for f in os.listdir(self.folder_path) if f.endswith('.gif')]
            if not self.gif_files:
                raise ValueError("No GIF files found in the specified folder.")
        except Exception as e:
            logging.error(f"Error loading GIF files: {e}")
            raise

    def play(self, gif_file):
        try:
            with Image.open(os.path.join(self.folder_path, gif_file)) as img:
                while True:
                    try:
                        img.seek(img.tell() + 1)
                    except EOFError:
                        img.seek(0)
                    frame = img.copy()
                    frame = ImageOps.pad(frame, (240, 240), color='black')
                    frame = frame.convert('RGB')
                    with canvas(self.device) as draw:
                        draw.bitmap((0, 0), frame)
                    time.sleep(img.info.get('duration', 100) / 1000.0)
        except Exception as e:
            logging.error(f"Error playing GIF {gif_file}: {e}")

    def run(self):
        try:
            while True:
                for gif_file in self.gif_files:
                    self.play(gif_file)
        except KeyboardInterrupt:
            logging.info("Received SIGINT, exiting...")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.device:
            try:
                self.device.hide()
                self.device.cleanup()
            except DeviceDisplayModeError as e:
                logging.error(f"Error during display cleanup: {e}")
            except Exception as e:
                logging.error(f"Unexpected error during cleanup: {e}")

def signal_handler(signum, frame):
    logging.info(f"Received signal {signum}, exiting...")
    raise KeyboardInterrupt

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        player = GifPlayer('/path/to/gif/folder')
        player.run()
    except Exception as e:
        logging.error(f"Application error: {e}")
    finally:
        logging.info("Application shutdown complete.")

