import sys
import time
import random
import logging
import argparse
import os
from contextlib import contextmanager

try:
    import RPi.GPIO as GPIO
except ImportError:
    # Mock RPi.GPIO for non-Raspberry Pi environments
    class GPIO:
        BCM = 'BCM'
        BOARD = 'BOARD'
        OUT = 'OUT'
        IN = 'IN'
        LOW = 'LOW'
        HIGH = 'HIGH'

        @staticmethod
        def setmode(mode):
            pass

        @staticmethod
        def setup(pin, direction):
            pass

        @staticmethod
        def cleanup():
            pass

        @staticmethod
        def output(pin, value):
            pass

@contextmanager
def gpio_setup(pins):
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in pins:
            GPIO.setup(pin, GPIO.OUT)
        yield
    finally:
        GPIO.cleanup()

def simulate_display_init():
    time.sleep(random.uniform(0.5, 1.0))

def simulate_busy_signal():
    time.sleep(random.uniform(2, 4))

def simulate_display_update(product_id, product_name, inventory, price):
    print(f"Updating display: {product_id} - {product_name}")
    print(f"Inventory: {inventory}")
    print(f"Price: ${price:.2f}")
    print("Simulated barcode: 123456789012")

def check_low_memory():
    try:
        os.urandom(1024 * 1024)  # Try to allocate 1MB
        return False
    except MemoryError:
        return True

def main():
    parser = argparse.ArgumentParser(description="Warehouse shelf label system simulation")
    parser.add_argument("--rst", type=int, default=17, help="RST pin")
    parser.add_argument("--dc", type=int, default=25, help="DC pin")
    parser.add_argument("--cs", type=int, default=8, help="CS pin")
    parser.add_argument("--busy", type=int, default=24, help="BUSY pin")
    parser.add_argument("--product-id", default="SKU-001", help="Product ID")
    parser.add_argument("--product-name", default="Example Product", help="Product name")
    parser.add_argument("--initial-inventory", type=int, default=50, help="Initial inventory")
    parser.add_argument("--initial-price", type=float, default=25.99, help="Initial price")
    args = parser.parse_args()

    logging.basicConfig(filename='epaper_errors.log', level=logging.ERROR,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    if random.random() < 0.1:
        logging.error("Simulated display initialization failure")
        sys.exit(1)

    with gpio_setup([args.rst, args.dc, args.cs, args.busy]):
        simulate_display_init()

        inventory = args.initial_inventory
        price = args.initial_price
        last_inventory_change = time.time()
        last_price_change = time.time()

        try:
            while True:
                current_time = time.time()

                if current_time - last_inventory_change >= 10:
                    inventory_change = random.randint(1, 5)
                    inventory = max(0, inventory - inventory_change)
                    last_inventory_change = current_time

                if current_time - last_price_change >= 30:
                    price_change = random.uniform(-1.00, 1.00)
                    price = max(0, price + price_change)
                    last_price_change = current_time

                if not check_low_memory():
                    simulate_busy_signal()
                    simulate_display_update(args.product_id, args.product_name, inventory, price)
                    time.sleep(5)
                else:
                    print("Low memory detected. Skipping update.")

                time.sleep(1)

        except KeyboardInterrupt:
            print("Keyboard interrupt received. Exiting...")
        except Exception as e:
            logging.error(f"Unexpected error: {str(e)}")
        finally:
            GPIO.cleanup()

if __name__ == "__main__":
    main()

