import smbus2
import time
import signal
import sys

# Constants
I2C_ADDRESS = 0x20
INPUT_REGISTER = 0x00
OUTPUT_REGISTER = 0x01
CONFIG_REGISTER = 0x06
I2C_BUS_NUMBER = 1
SLEEP_INTERVAL = 0.1

# Initialize I2C bus
bus = smbus2.SMBus(I2C_BUS_NUMBER)

def setup_expander():
    try:
        # Set all pins as inputs with pull-up enabled
        bus.write_byte_data(I2C_ADDRESS, CONFIG_REGISTER, 0xFF)
    except IOError as e:
        print(f"Error setting up expander: {e}")
        sys.exit(1)

def read_sensors():
    try:
        # Read the input register
        return bus.read_byte_data(I2C_ADDRESS, INPUT_REGISTER)
    except IOError as e:
        print(f"Error reading sensors: {e}")
        return None

def cleanup(signum, frame):
    print("\nCleaning up...")
    bus.close()
    sys.exit(0)

def main():
    setup_expander()
    signal.signal(signal.SIGINT, cleanup)

    try:
        while True:
            sensor_states = read_sensors()
            if sensor_states is not None:
                for i in range(8):
                    if not (sensor_states & (1 << i)):  # Check if bit i is LOW
                        print(f"Obstacle detected by sensor {i}")
            time.sleep(SLEEP_INTERVAL)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup(None, None)

if __name__ == "__main__":
    main()

