import time
import logging
import subprocess
from datetime import datetime
from gpiozero import InputDevice
from signal import signal, SIGINT

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize GPIO pins
def initialize_gpio():
    try:
        light_sensor = InputDevice(17, pull_up=False)
        temp_sensor = InputDevice(4, pull_up=False)
        logging.info("GPIO pins initialized successfully.")
        return light_sensor, temp_sensor
    except Exception as e:
        logging.error(f"Failed to initialize GPIO pins: {e}")
        return None, None

# Simulate light sensor reading
def simulate_light_sensor(light_sensor):
    try:
        current_hour = datetime.now().hour
        if 6 <= current_hour < 18:
            lux = 600 + (light_sensor.value * 400)  # Simulate light level between 600-1000 lux
        else:
            lux = 100 + (light_sensor.value * 200)  # Simulate light level between 100-300 lux
        return lux
    except Exception as e:
        logging.error(f"Error reading light sensor: {e}")
        return 0

# Simulate temperature sensor reading
def simulate_temp_sensor(temp_sensor):
    try:
        temperature = 20 + (temp_sensor.value * 10)  # Simulate temperature between 20-30°C
        return temperature
    except Exception as e:
        logging.error(f"Error reading temperature sensor: {e}")
        return 0

# Simulate voltage and current readings
def simulate_voltage_current(lux):
    try:
        if lux > 300:
            voltage = 11.5 + (lux * 0.005)  # Simulate voltage between 11.5-12.5V
            current = 1.5 + (lux * 0.0005)  # Simulate current between 1.5-2.5A
        else:
            voltage = 10.0 + (lux * 0.002)  # Simulate voltage between 10.0-11.0V
            current = 0.5 + (lux * 0.0002)  # Simulate current between 0.5-1.0A
        return voltage, current
    except Exception as e:
        logging.error(f"Error simulating voltage and current: {e}")
        return 0, 0

# Read Raspberry Pi's internal temperature
def read_pi_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=2)
        if result.returncode == 0:
            temp_str = result.stdout.strip()
            temp_value = float(temp_str.split('=')[1].split("'")[0])
            return temp_value
        else:
            logging.warning("vcgencmd failed to read temperature.")
            return None
    except FileNotFoundError:
        logging.warning("vcgencmd not found.")
        return None
    except Exception as e:
        logging.error(f"Error reading Pi temperature: {e}")
        return None

# Log sensor data and trigger actions
def log_and_trigger_actions(lux, temperature, voltage, current, pi_temp):
    logging.info(f"Light: {lux:.2f} lux, Temperature: {temperature:.2f} °C, Voltage: {voltage:.2f} V, Current: {current:.2f} A, Pi Temp: {pi_temp if pi_temp is not None else 'N/A'} °C")

    if lux < 300:
        logging.warning("WARNING: Possible solar panel performance issues.")

    if temperature > 35:
        logging.warning("WARNING: Simulated cooling-system activation.")

    if pi_temp is not None and pi_temp > 75:
        logging.critical("CRITICAL: Simulated system shutdown.")

# Main function
def main():
    light_sensor, temp_sensor = initialize_gpio()
    if light_sensor is None or temp_sensor is None:
        return

    def signal_handler(sig, frame):
        logging.info("Program interrupted. Cleaning up...")
        light_sensor.close()
        temp_sensor.close()
        exit(0)

    signal(SIGINT, signal_handler)

    try:
        while True:
            lux = simulate_light_sensor(light_sensor)
            temperature = simulate_temp_sensor(temp_sensor)
            voltage, current = simulate_voltage_current(lux)
            pi_temp = read_pi_temperature()
            log_and_trigger_actions(lux, temperature, voltage, current, pi_temp)
            time.sleep(5)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        light_sensor.close()
        temp_sensor.close()

if __name__ == '__main__':
    main()

