import serial
import time

def read_temperature():
    try:
        # Open the serial port
        ser = serial.Serial(
            port='/dev/ttyUSB0',
            baudrate=115200,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1
        )

        print("Serial port opened successfully.")

        try:
            while True:
                try:
                    # Read a line from the serial port
                    line = ser.readline().decode('ascii').strip()
                    if line:
                        # Attempt to parse the first floating-point number in the line
                        parts = line.split()
                        for part in parts:
                            try:
                                temperature = float(part)
                                print(f'Temperature: {temperature:.1f} C')
                                break
                            except ValueError:
                                continue
                except ValueError as ve:
                    print(f"Error parsing data: {ve}")
                except serial.SerialException as se:
                    print(f"Serial error: {se}")
                    break

                # Wait for 0.5 seconds before the next read
                time.sleep(0.5)

        except KeyboardInterrupt:
            print("Program terminated by user.")

        finally:
            # Ensure the serial port is closed
            if ser.is_open:
                ser.close()
                print("Serial port closed.")

    except serial.SerialException as se:
        print(f"Failed to open serial port: {se}")

if __name__ == "__main__":
