import RPi.GPIO as GPIO
import time
import csv
from datetime import datetime

DHT_PIN = 4

def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.OUT)
        return True
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        return False

def cleanup_gpio():
    GPIO.cleanup()

def read_dht22():
    try:
        GPIO.output(DHT_PIN, GPIO.LOW)
        time.sleep(0.018)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        # Wait for the sensor to respond
        start_time = time.time()
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            if time.time() - start_time > 0.2:
                return None, None

        start_time = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() - start_time > 0.2:
                return None, None

        data = []
        for _ in range(40):
            start_time = time.time()
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() - start_time > 0.00005:
                    return None, None

            start_time = time.time()
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() - start_time > 0.00025:
                    return None, None

            pulse_duration = time.time() - start_time
            data.append(0 if pulse_duration < 0.000025 else 1)

        humidity = data[0:16]
        temperature = data[16:32]
        checksum = data[32:40]

        humidity_decimal = humidity[0:8]
        humidity_integer = humidity[8:16]
        temperature_decimal = temperature[0:8]
        temperature_integer = temperature[8:16]
        temperature_sign = temperature_integer[0]

        humidity_int = int(''.join(map(str, humidity_integer)), 2)
        humidity_dec = int(''.join(map(str, humidity_decimal)), 2) / 10.0
        humidity = humidity_int + humidity_dec

        temperature_int = int(''.join(map(str, temperature_integer[1:])), 2)
        temperature_dec = int(''.join(map(str, temperature_decimal)), 2) / 10.0
        if temperature_sign:
            temperature = -temperature_int - temperature_dec
        else:
            temperature = temperature_int + temperature_dec

        checksum_calc = (humidity_int + humidity_dec + temperature_int + temperature_dec) & 0xFF
        checksum_data = int(''.join(map(str, checksum)), 2)

        if checksum_calc != checksum_data:
            return None, None

        return temperature, humidity

    except Exception as e:
        print(f"Error reading DHT22: {e}")
        return None, None

def main():
    if not setup_gpio():
        return

    try:
        with open('humidity_log.txt', 'a', newline='') as csvfile:
            csv_writer = csv.writer(csvfile)
            while True:
                temperature, humidity = read_dht22()
                if temperature is not None and humidity is not None:
                    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                    csv_writer.writerow([timestamp, f"{temperature:.1f}", f"{humidity:.1f}"])
                    print(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
                else:
                    print("Failed to read from DHT22 sensor")
                time.sleep(10)
    except KeyboardInterrupt:
        print("Program interrupted by user")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

