import serial
import csv
import os
import time
from datetime import datetime
import sys

def celsius_to_fahrenheit(celsius):
    return celsius * 9/5 + 32

def main():
    serial_port = '/dev/ttyACM0'
    baud_rate = 115200
    timeout = 1  # 1 second timeout
    csv_file = 'temperature_log.csv'

    try:
        ser = serial.Serial(serial_port, baud_rate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port {serial_port}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Check if the CSV file exists to determine if we need to write the header
        file_exists = os.path.isfile(csv_file)

        with open(csv_file, mode='a', newline='') as file:
            writer = csv.writer(file)

            # Write the header if the file does not exist
            if not file_exists:
                writer.writerow(['timestamp', 'celsius', 'fahrenheit'])

            while True:
                try:
                    line = ser.readline().decode('ascii').strip()
                    if line:
                        try:
                            celsius = float(line)
                            fahrenheit = celsius_to_fahrenheit(celsius)
                            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                            writer.writerow([timestamp, celsius, fahrenheit])
                        except ValueError:
                            print(f"Warning: Malformed line: {line}", file=sys.stderr)
                except KeyboardInterrupt:
                    print("KeyboardInterrupt received. Exiting...")
                    break
                except Exception as e:
                    print(f"Error reading from serial port: {e}", file=sys.stderr)
    finally:
        ser.close()

if __name__ == "__main__":
    main()

