import time
import logging
from smbus2 import SMBus, SMBusError
from contextlib import contextmanager

class DHT20:
    def __init__(self, bus_number=1, address=0x38):
        self.bus_number = bus_number
        self.address = address
        self.bus = None
        self.last_read_time = 0
        self.cached_result = (None, None, False)
        self.logger = logging.getLogger('DHT20')
        self.logger.setLevel(logging.DEBUG)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def begin(self):
        try:
            self.bus = SMBus(self.bus_number)
            time.sleep(0.5)
            status = self.bus.read_byte_data(self.address, 0x71)
            if (status & 0x18) != 0x18:
                self.logger.error("Status check failed.")
                return False
            return True
        except OSError as e:
            self.logger.error(f"Failed to open I2C bus: {e}")
            return False

    def trigger_measurement(self):
        try:
            self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
        except OSError as e:
            self.logger.error(f"Failed to trigger measurement: {e}")
            return False
        return True

    def wait_for_measurement(self):
        for _ in range(10):
            try:
                status = self.bus.read_byte_data(self.address, 0x71)
                if not (status & 0x80):
                    return True
            except OSError as e:
                self.logger.warning(f"Timeout waiting for measurement: {e}")
            time.sleep(0.08)
        return False

    def read_data(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
            crc = self.calculate_crc8(data[:6])
            if crc != data[6]:
                self.logger.warning("CRC mismatch.")
                return None, None, False
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
            humidity = humidity_raw / (2**20) * 100
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
            temperature = temperature_raw / (2**19) * 200 - 50
            return temperature, humidity, False
        except OSError as e:
            self.logger.error(f"Failed to read data: {e}")
            return None, None, True

    def calculate_crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_read_time < 2:
            return self.cached_result

        for _ in range(5):
            if not self.trigger_measurement():
                continue
            if not self.wait_for_measurement():
                continue
            temperature, humidity, error = self.read_data()
            if not error:
                self.cached_result = (temperature, humidity, False)
                self.last_read_time = current_time
                return self.cached_result
            time.sleep(0.01)

        self.cached_result = (None, None, True)
        return self.cached_result

    def close(self):
        if self.bus:
            self.bus.close()

    @contextmanager
    def __enter__(self):
        if not self.begin():
            raise RuntimeError("Failed to initialize DHT20 sensor.")
        try:
            yield self
        finally:
            self.close()

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

# Example usage
if __name__ == "__main__":
    try:
        with DHT20() as dht20:
            while True:
                temperature, humidity, error = dht20.get_temperature_and_humidity()
                if error:
                    print("Failed to get reading.")
                else:
                    print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting...")
    except SystemExit:
        print("System exit.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        print("Program terminated.")

