import busio
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(filename='error.log', level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')
alert_logger = logging.getLogger('alert_logger')
alert_logger.addHandler(logging.FileHandler('retail_alerts.log'))
cloud_logger = logging.getLogger('cloud_logger')
cloud_logger.addHandler(logging.FileHandler('cloud_log.log'))

# GPIO setup
dht1 = DHT22(board.D17, use_pulseio=False)
dht2 = DHT22(board.D27, use_pulseio=False)

# Alert tracking
high_humidity_alerts = {17: 0, 27: 0}
low_humidity_alerts = {17: 0, 27: 0}
last_alert_time = {17: datetime.min, 27: datetime.min}

# MQTT setup
mqtt_client = mqtt.Client()
mqtt_client.connect("mqtt.example.com", 1883, 60)

def cleanup(signum, frame):
    try:
        dht1.exit()
        dht2.exit()
        mqtt_client.disconnect()
    except Exception as e:
        logging.error("Error during cleanup: %s", e, exc_info=True)
    sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

def log_alert(sensor_pin, message):
    alert_logger.info(f"Sensor {sensor_pin}: {message}")
    mqtt_client.publish(f"sensors/{sensor_pin}/alert", message)

def check_alert(sensor_pin, humidity):
    global high_humidity_alerts, low_humidity_alerts, last_alert_time
    current_time = datetime.now()
    if humidity > 75:
        high_humidity_alerts[sensor_pin] += 1
        low_humidity_alerts[sensor_pin] = 0
    elif humidity < 45:
        low_humidity_alerts[sensor_pin] += 1
        high_humidity_alerts[sensor_pin] = 0
    else:
        high_humidity_alerts[sensor_pin] = 0
        low_humidity_alerts[sensor_pin] = 0

    if high_humidity_alerts[sensor_pin] >= 3:
        if current_time - last_alert_time[sensor_pin] > timedelta(minutes=30):
            log_alert(sensor_pin, "High Humidity Alert")
            last_alert_time[sensor_pin] = current_time
    elif low_humidity_alerts[sensor_pin] >= 3:
        if current_time - last_alert_time[sensor_pin] > timedelta(minutes=30):
            log_alert(sensor_pin, "Low Humidity Alert")
            last_alert_time[sensor_pin] = current_time

def read_sensor(sensor):
    for attempt in range(3):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if 0 <= humidity <= 100 and 0 <= temperature <= 35:
                return temperature, humidity
        except Exception as e:
            logging.error("Sensor read error: %s", e, exc_info=True)
            time.sleep(2)
    return None, None

def write_to_csv(data):
    filename = f"retail_data_{datetime.now().strftime('%Y-%m-%d')}.csv"
    try:
        with open(filename, 'a', newline='') as csvfile:
            fcntl.flock(csvfile, fcntl.LOCK_EX)
            writer = csv.writer(csvfile)
            writer.writerow(data)
            fcntl.flock(csvfile, fcntl.LOCK_UN)
    except Exception as e:
        logging.error("CSV write error: %s", e, exc_info=True)

def simulate_cloud_push(data):
    success = random.random() < 0.8
    cloud_logger.info(f"Cloud push attempt: {'Success' if success else 'Failure'} - Data: {data}")
    return success

def main():
    while True:
        try:
            for sensor, pin in [(dht1, 17), (dht2, 27)]:
                temperature, humidity = read_sensor(sensor)
                if temperature is not None and humidity is not None:
                    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                    data = [timestamp, pin, temperature, humidity]
                    write_to_csv(data)
                    check_alert(pin, humidity)
                    if simulate_cloud_push(data):
                        mqtt_client.publish(f"sensors/{pin}/data", str(data))
                else:
                    logging.error(f"Failed to read from sensor {pin} after 3 attempts")
            time.sleep(60)
        except Exception as e:
            logging.error("Main loop error: %s", e, exc_info=True)
            time.sleep(60)

if __name__ == "__main__":
    main()

