# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class FanController:
    def __init__(self, gpio_pin=14):
        self.fan = PWMOutputDevice(gpio_pin, frequency=100)
        self.duty_cycles = {
            70: 1.0,
            60: 0.85,
            50: 0.70,
            40: 0.50,
            32: 0.25,
            25: 0.15
        }
        self.default_duty_cycle = 0.0

    def get_cpu_temperature(self):
        try:
            # Attempt to read temperature using vcgencmd
            output = check_output(['vcgencmd', 'measure_temp']).decode('utf-8')
            temp_str = output.strip().split('=')[1].split("'")[0]
            return float(temp_str)
        except (IndexError, CalledProcessError, ValueError):
            try:
                # Fallback to reading from the file system
                with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                    temp = int(f.read().strip()) / 1000.0
                    return temp
            except (IOError, ValueError):
                logging.error("Failed to read CPU temperature.")
                return None

    def set_fan_speed(self, temperature):
        if temperature is None:
            return

        logging.info(f"Current temperature: {temperature}°C")

        for temp_threshold, duty_cycle in sorted(self.duty_cycles.items(), reverse=True):
            if temperature > temp_threshold:
                self.fan.value = duty_cycle
                logging.info(f"Setting fan speed to {duty_cycle * 100}%")
                return

        self.fan.value = self.default_duty_cycle
        logging.info(f"Setting fan speed to {self.default_duty_cycle * 100}%")

    def run(self):
        try:
            while True:
                temperature = self.get_cpu_temperature()
                self.set_fan_speed(temperature)
                time.sleep(5)
        except KeyboardInterrupt:
            logging.info("Program terminated by user.")
        finally:
            self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up GPIO resources.")
        self.fan.close()

def signal_handler(signum, frame):
    logging.info(f"Received signal {signum}, terminating program.")
    raise KeyboardInterrupt

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    fan_controller = FanController()
    fan_controller.run()
