import matplotlib.pyplot as plt
import numpy as np
import time
from matplotlib.animation import FuncAnimation

def read_frame(serial_port):
    try:
        line = serial_port.readline().decode('utf-8').strip()
        if not line:
            return None
        tokens = line.split(',')
        frame = []
        for token in tokens:
            try:
                frame.append(int(token))
            except ValueError:
                continue
        if len(frame) == 768:
            return np.array(frame).reshape((24, 32))
        else:
            return None
    except Exception as e:
        print(f"Error reading frame: {e}")
        return None

def update_display(frame, img):
    if frame is not None:
        img.set_array(frame)
    return img,

def main():
    serial_port = None
    try:
        serial_port = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
        return

    last_good_frame = None
    fig, ax = plt.subplots()
    img = ax.imshow(np.zeros((24, 32)), cmap='inferno', interpolation='nearest', vmin=0, vmax=255)
    ani = FuncAnimation(fig, update_display, fargs=(img,), interval=100, blit=True)

    try:
        while True:
            frame = read_frame(serial_port)
            if frame is not None:
                last_good_frame = frame
            elif last_good_frame is not None:
                img.set_array(last_good_frame)
            plt.pause(0.1)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()
        plt.close(fig)

if __name__ == "__main__":
    main()

