import smbus2
import time
import signal
import sys

# Constants
MCP23017_ADDRESS = 0x20
IODIRA = 0x00
IODIRB = 0x01
GPPUA = 0x0C
GPPUB = 0x0D
GPIOA = 0x12
GPIOB = 0x13
OLATA = 0x14
OLATB = 0x15

# LED on GPA0, Switch on GPB7
LED_PIN = 0
SWITCH_PIN = 7

# Retry settings
MAX_RETRIES = 3
RETRY_DELAY = 0.5

# Initialize I2C bus
bus = smbus2.SMBus(0)

def write_register(register, value):
    for attempt in range(MAX_RETRIES):
        try:
            bus.write_byte_data(MCP23017_ADDRESS, register, value)
            return
        except IOError:
            if attempt < MAX_RETRIES - 1:
                time.sleep(RETRY_DELAY)
            else:
                raise

def read_register(register):
    for attempt in range(MAX_RETRIES):
        try:
            return bus.read_byte_data(MCP23017_ADDRESS, register)
        except IOError:
            if attempt < MAX_RETRIES - 1:
                time.sleep(RETRY_DELAY)
            else:
                raise

def setup():
    # Set GPA0 as output and GPB7 as input with pull-up
    write_register(IODIRA, 0b11111110)  # GPA0 as output
    write_register(IODIRB, 0b11111111)  # GPB7 as input
    write_register(GPPUB, 0b10000000)   # Enable pull-up on GPB7

def cleanup():
    # Turn off LED
    write_register(OLATA, 0b00000001)
    bus.close()

def main():
    setup()
    previous_state = None

    try:
        while True:
            # Read switch state
            gpio_b = read_register(GPIOB)
            switch_state = (gpio_b & (1 << SWITCH_PIN)) == 0  # LOW is pressed

            # Update LED based on switch state
            if switch_state:
                write_register(OLATA, 0b00000001)  # Turn LED ON
                current_state = "ON"
            else:
                write_register(OLATA, 0b00000000)  # Turn LED OFF
                current_state = "OFF"

            # Print state change
            if current_state != previous_state:
                print(f"Led {current_state}")
                previous_state = current_state

            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

