import signal
import time
import math
from gpiozero import PWMOutputDevice, Button
from gpiozero.exc import GPIOZeroError

def setup():
    try:
        buzzer = PWMOutputDevice(pin=11, frequency=2000, initial_value=0)
        button = Button(pin=12, pull_up=True)
        return buzzer, button
    except GPIOZeroError as e:
        print(f"Error setting up GPIO: {e}")
        return None, None

def play_alert(buzzer, duration=2, duty_cycle=0.5, time_step=0.001, freq_variation=500):
    start_time = time.time()
    while time.time() - start_time < duration:
        for offset in range(-freq_variation, freq_variation + 1, 1):
            frequency = 2000 + offset
            buzzer.frequency = frequency
            buzzer.value = duty_cycle
            time.sleep(time_step)

def cleanup(buzzer, button):
    if buzzer:
        buzzer.close()
    if button:
        button.close()

def signal_handler(signum, frame):
    print("Signal received, cleaning up...")
    cleanup(buzzer, button)
    exit(0)

def main():
    global buzzer, button
    buzzer, button = setup()
    if buzzer is None or button is None:
        print("Failed to initialize hardware. Exiting.")
        return

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            if button.is_pressed:
                print("Button pressed. Playing alert.")
                play_alert(buzzer)
            time.sleep(0.1)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup(buzzer, button)

if __name__ == "__main__":
    main()

