import RPi.GPIO as GPIO
import time
import requests
import sys
import signal

# Constants
GPIO_PIN = 17
CHECK_INTERVAL = 1  # seconds
POST_URL = "http://example.com/alert"
POST_TIMEOUT = 5  # seconds
POST_PAYLOAD = {"alert": "Power failure detected"}

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(GPIO_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def cleanup_gpio():
    GPIO.cleanup()

def send_alert():
    try:
        response = requests.post(POST_URL, json=POST_PAYLOAD, timeout=POST_TIMEOUT)
        response.raise_for_status()
        print("Alert sent successfully.")
    except requests.exceptions.RequestException as e:
        print(f"Failed to send alert: {e}")

def signal_handler(sig, frame):
    print("Exiting...")
    cleanup_gpio()
    sys.exit(0)

def main():
    setup_gpio()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            pin_state = GPIO.input(GPIO_PIN)
            if pin_state == GPIO.HIGH:
                print("Power is present (HIGH)")
            else:
                print("Power failure detected (LOW)")
                send_alert()
            time.sleep(CHECK_INTERVAL)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

import RPi.GPIO as GPIO
import time

# Set up GPIO mode
