# Define sensor pins
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Set up sensor pins as inputs
GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN)
GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN)

def read_sensors():
    """Read the state of the two IR sensors."""
    try:
        left_value = GPIO.input(LEFT_SENSOR_PIN)
        right_value = GPIO.input(RIGHT_SENSOR_PIN)
        return left_value, right_value
    except Exception as e:
        print(f"Error reading sensors: {e}")
        return None, None

def determine_direction(left_value, right_value):
    """Determine the direction based on sensor values."""
    if left_value == 0 and right_value == 0:
        return "forward"
    elif left_value == 1 and right_value == 0:
        return "turn-left"
    elif left_value == 0 and right_value == 1:
        return "turn-right"
    else:
        return "search"

