from gpiozero import MotionSensor
from gpiozero.pins.mock import MockFactory
from gpiozero.exc import GPIOZeroError

class SolarArrayMonitor:
    def __init__(self, pin=17, debounce_time=2.0, poll_samples=10, poll_interval=0.5):
        self.pin = pin
        self.debounce_time = debounce_time
        self.poll_samples = poll_samples
        self.poll_interval = poll_interval
        self.detection_events = []
        self.sensor = None
        self.setup_sensor()

    def setup_sensor(self):
        try:
            self.sensor = MotionSensor(self.pin, debounce_time=self.debounce_time)
            self.sensor.when_motion = self.handle_motion
        except GPIOZeroError as e:
            print(f"Failed to initialize sensor: {e}")
            sys.exit(1)

    def handle_motion(self):
        timestamp = datetime.now().isoformat()
        self.detection_events.append(timestamp)
        print(f"Motion detected at {timestamp}")

    def get_occupancy_statistics(self):
        return len(self.detection_events)

    def run(self):
        try:
            for _ in range(self.poll_samples):
                time.sleep(self.poll_interval)
            self.print_summary()
        except Exception as e:
            print(f"Runtime error: {e}")
        finally:
            self.cleanup()

    def print_summary(self):
        print("Summary Report:")
        print(f"Total motion detection events: {self.get_occupancy_statistics()}")
        print("Detection Events:")
        for event in self.detection_events:
            print(event)

    def cleanup(self):
        if self.sensor:
            self.sensor.close()
            print("Sensor resources released.")

def signal_handler(sig, frame):
    print("Signal received, cleaning up and exiting.")
    monitor.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

