    if 'GPIOZERO_PIN_FACTORY' in os.environ:
        from gpiozero.pins.mock import MockFactory
        MotionSensor.pin_factory = MockFactory()

    monitor = SolarArrayMonitor()
    monitor.run()
    sys.exit(0)

