import pigpio
import threading
import signal
import sys

class OutputPin:
    def __init__(self, pin, value_list, initial_value):
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise RuntimeError("Failed to connect to pigpio daemon")

        if not (0 <= pin <= 27):
            raise ValueError("Invalid GPIO pin number")

        if initial_value not in value_list:
            raise ValueError("Initial value not in value_list")

        self.pin = pin
        self.value_list = value_list
        self.current_value = initial_value
        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.pi.write(self.pin, self.current_value)

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError("Value not in value_list")
        self.pi.write(self.pin, value)
        self.current_value = value

    def shutdown(self):
        self.pi.set_mode(self.pin, pigpio.INPUT)
        self.pi.stop()

class TriggerPin(OutputPin):
    def __init__(self, pin, pulse_duration, pulse_high=True):
        super().__init__(pin, (0, 1), 0)
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high
        self.lock = threading.Lock()

    def trigger(self):
        with self.lock:
            if self.pulse_high:
                self.pi.write(self.pin, 1)
                self.pi.sleep(self.pulse_duration)
                self.pi.write(self.pin, 0)
            else:
                self.pi.write(self.pin, 0)
                self.pi.sleep(self.pulse_duration)
                self.pi.write(self.pin, 1)

def shutdown_pins(pins):
    for pin in pins:
        pin.shutdown()
    sys.exit(0)

if __name__ == "__main__":
    try:
        ExampleOutput = OutputPin(21, (0, 1), 0)
        ExampleTrigger = TriggerPin(20, 100, pulse_high=True)

        pins = [ExampleOutput, ExampleTrigger]

        signal.signal(signal.SIGINT, lambda signum, frame: shutdown_pins(pins))

        # Example usage
        ExampleOutput.set_value(1)
        ExampleTrigger.trigger()

    except Exception as e:
        print(f"Error: {e}")
        shutdown_pins(pins)

