import signal
import time
import logging
import zmq
from gpiozero import PWMOutputDevice, OutputDevice
from datetime import datetime, timedelta

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

class PIDHandler:
    def __init__(self, pwm=True):
        self.global_err_state = False
        self.last_msg = datetime.now()
        self.pwm = pwm

        try:
            if self.pwm:
                self.error_output = PWMOutputDevice(pin=12, frequency=1000, initial_value=0.0)
            else:
                self.error_output = OutputDevice(pin=10)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            raise

        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def update_error_output(self):
        try:
            if self.pwm:
                self.error_output.value = 1.0 if self.global_err_state else 0.0
            else:
                self.error_output.value = self.global_err_state
        except Exception as e:
            logging.error(f"Failed to update error output: {e}")

    def set_error_output(self, state: bool):
        try:
            self.global_err_state = state
            self.update_error_output()
        except Exception as e:
            logging.error(f"Failed to set error output: {e}")

    def handle_message(self, socket):
        try:
            message = socket.recv(zmq.NOBLOCK)
            self.last_msg = datetime.now()
            # Process the message here
            logging.debug(f"Received message: {message}")
        except zmq.Again:
            if datetime.now() - self.last_msg > timedelta(seconds=20):
                self.set_error_output(True)
        except Exception as e:
            logging.error(f"Error handling message: {e}")

    def cleanup(self, signum=None, frame=None):
        logging.info("Cleaning up resources...")
        try:
            self.error_output.close()
        except Exception as e:
            logging.error(f"Error closing GPIO device: {e}")
        logging.info("Cleanup complete.")
        exit(0)

# Example usage
if __name__ == "__main__":
    pid_handler = PIDHandler(pwm=True)

    context = zmq.Context()
    socket = context.socket(zmq.SUB)
    socket.connect("tcp://localhost:5555")
    socket.setsockopt_string(zmq.SUBSCRIBE, "")

    try:
        while True:
            pid_handler.handle_message(socket)
            time.sleep(0.1)
    except KeyboardInterrupt:
        pid_handler.cleanup()

