import pigpio
import time
from typing import Optional

class PigpioConnectionError(Exception):
    pass

class InvalidPinNumberError(Exception):
    pass

class InvalidValueError(Exception):
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise InvalidPinNumberError(f"Pin number {pin_number} is out of range (0-31).")
        if initial_value not in (0, 1):
            raise InvalidValueError(f"Initial value {initial_value} must be 0 or 1.")

        self.pin_number = pin_number
        self.pi: Optional[pigpio.pi] = None

        try:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise PigpioConnectionError("Failed to connect to pigpio daemon.")
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
            self.pi.write(self.pin_number, initial_value)
        except Exception as e:
            self.shutdown()
            raise e

    def set_value(self, value: int):
        if value not in (0, 1):
            raise InvalidValueError(f"Value {value} must be 0 or 1.")
        try:
            self.pi.write(self.pin_number, value)
        except Exception as e:
            self.shutdown()
            raise e

    def shutdown(self):
        if self.pi is not None:
            try:
                self.pi.set_mode(self.pin_number, pigpio.INPUT)
            except:
                pass
            self.pi.stop()
            self.pi = None

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 0)
        for _ in range(10):
            pin.set_value(1)
            time.sleep(0.5)
            pin.set_value(0)
            time.sleep(0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        pin.shutdown()

