import signal
import logging
from gpiozero import DigitalInputDevice
from time import sleep

class RotaryEncoder:
    def __init__(self, clk_pin=17, dt_pin=18, callback=None):
        self.clk = DigitalInputDevice(clk_pin, pull_up=True, bounce_time=0.02)
        self.dt = DigitalInputDevice(dt_pin, pull_up=True, bounce_time=0.02)
        self.counter = 0
        self.last_state = 0
        self.callback = callback if callable(callback) else None

        self.clk.when_activated = self._handle_clk
        self.clk.when_deactivated = self._handle_clk
        self.dt.when_activated = self._handle_dt
        self.dt.when_deactivated = self._handle_dt

    def _handle_clk(self, pin):
        self._update_counter()

    def _handle_dt(self, pin):
        self._update_counter()

    def _update_counter(self):
        state = (self.clk.value << 1) | self.dt.value
        if state == 0b00 and self.last_state == 0b01:
            self.counter += 1
        elif state == 0b01 and self.last_state == 0b00:
            self.counter -= 1
        self.last_state = state
        if self.callback:
            self.callback(self.counter)

    def cleanup(self):
        self.clk.close()
        self.dt.close()

def signal_handler(encoder):
    logging.info("Received exit signal, cleaning up...")
    encoder.cleanup()
    exit(0)

def main():
    logging.basicConfig(level=logging.INFO)

    try:
        encoder = RotaryEncoder(callback=lambda x: logging.info(f"Counter: {x}"))
        signal.signal(signal.SIGINT, lambda signum, frame: signal_handler(encoder))
        signal.signal(signal.SIGTERM, lambda signum, frame: signal_handler(encoder))

        logging.info("Rotary encoder running. Press Ctrl-C to exit.")
        while True:
            sleep(1)

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if 'encoder' in locals():
            encoder.cleanup()

if __name__ == "__main__":
    main()

