from gpiozero import InputDevice
from signal import pause
import sys

class RotaryEncoder:
    def __init__(self, clk_pin=17, dt_pin=18, callback=None):
        self.clk = InputDevice(clk_pin, pull_up=True, bounce_time=0.005)
        self.dt = InputDevice(dt_pin, pull_up=True, bounce_time=0.005)
        self.counter = 0
        self.last_clk_state = self.clk.value
        self.callback = callback

        if callback is not None and not callable(callback):
            raise ValueError("Callback must be callable")

        self.clk.when_activated = self._clk_rising
        self.clk.when_deactivated = self._clk_falling

    def _clk_rising(self):
        self._update_counter()

    def _clk_falling(self):
        self._update_counter()

    def _update_counter(self):
        if self.clk.value != self.last_clk_state:
            if self.dt.value != self.clk.value:
                self.counter += 1
            else:
                self.counter -= 1
            self.last_clk_state = self.clk.value
            if self.callback:
                try:
                    self.callback(self.counter)
                except Exception as e:
                    print(f"Error in callback: {e}", file=sys.stderr)

    def cleanup(self):
        self.clk.close()
        self.dt.close()

def main():
    def on_rotation(counter):
        print(f"Counter: {counter}")

    encoder = RotaryEncoder(callback=on_rotation)

    try:
        pause()
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        encoder.cleanup()

