import time
import board
import busio
from adafruit_tsl2561 import TSL2561
from gpiozero import PWMLED
from signal import signal, SIGINT

# Constants
I2C_ADDRESS = 0x39
PWM_FREQUENCY = 1000
SLEEP_INTERVAL = 1
MAX_RETRIES = 3

# Initialize I2C and TSL2561 sensor
i2c = busio.I2C(board.SCL, board.SDA)
tsl = None
led = PWMLED(18, frequency=PWM_FREQUENCY)

def initialize_sensor():
    global tsl
    for attempt in range(MAX_RETRIES):
        try:
            tsl = TSL2561(i2c, address=I2C_ADDRESS)
            return True
        except Exception as e:
            print(f"Attempt {attempt + 1}: Failed to initialize TSL2561 sensor: {e}")
            time.sleep(1)
    return False

def clamp(value, min_value, max_value):
    return max(min_value, min(value, max_value))

def cleanup(signum, frame):
    print("\nCleaning up resources...")
    if tsl:
        tsl.deinit()
    led.close()
    i2c.deinit()
    print("Resources cleaned up. Exiting.")
    exit(0)

# Register the cleanup function to handle SIGINT and other termination signals
signal(SIGINT, cleanup)

# Main loop
def main():
    if not initialize_sensor():
        print("Failed to initialize TSL2561 sensor after multiple attempts. Exiting.")
        return

    try:
        while True:
            try:
                lux = tsl.lux
                if lux is not None:
                    brightness = clamp(lux / 10, 0, 100)
                    led.value = brightness / 100
                    print(f"Lux: {lux:.2f}, Brightness: {brightness:.2f}%")
                else:
                    print("Failed to read lux value.")
            except Exception as e:
                print(f"Error reading sensor: {e}")

            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        cleanup(None, None)

if __name__ == "__main__":
    main()

