import RPi.GPIO as GPIO
import time
import sys
import argparse
import logging
import signal

# Set up logging
logging.basicConfig(filename='error.log', level=logging.ERROR)

# Digit to duty cycle mapping
DIGIT_TO_DUTY_CYCLE = {
    '0': 0, '1': 20, '2': 40, '3': 60, '4': 80,
    '5': 100, '6': 80, '7': 20, '8': 100, '9': 80,
    '.': 100  # Decimal point placeholder
}

def digit_to_duty_cycle(digit):
    return DIGIT_TO_DUTY_CYCLE.get(digit, 0)

def display_price(price, gpio_pins, frequency, duty_cycle, display_time, simulate):
    if price < 0 or price > 99.99:
        price_str = "Err"
    else:
        price_str = f"{price:05.2f}"

    duty_cycles = [digit_to_duty_cycle(digit) for digit in price_str]

    if simulate:
        print(f"Simulated duty cycles: {duty_cycles}")
    else:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            for pin in gpio_pins:
                GPIO.setup(pin, GPIO.OUT)
                pwm = GPIO.PWM(pin, frequency)
                pwm.start(0)

            for _ in range(int(display_time * 10)):  # 10 updates per second
                for i, pin in enumerate(gpio_pins):
                    pwm = GPIO.PWM(pin, frequency)
                    pwm.start(duty_cycles[i])
                time.sleep(0.1)

        except Exception as e:
            logging.error(f"Error displaying price: {e}")
        finally:
            GPIO.cleanup()

def main():
    parser = argparse.ArgumentParser(description="Display formatted price on GPIO PWM outputs.")
    parser.add_argument("price", type=float, help="Price to display")
    parser.add_argument("gpio_pins", type=int, nargs=4, help="Four GPIO pin numbers")
    parser.add_argument("frequency", type=int, help="PWM frequency (100-1000 Hz)")
    parser.add_argument("duty_cycle", type=float, help="Duty cycle (0-100 percent)")
    parser.add_argument("display_time", type=float, nargs='?', default=10, help="Display time in seconds")
    parser.add_argument("--simulate", action="store_true", help="Simulate the display without GPIO")

    args = parser.parse_args()

    if not (100 <= args.frequency <= 1000):
        logging.error("Frequency must be between 100 and 1000 Hz")
        sys.exit(1)

    if not (0 <= args.duty_cycle <= 100):
        logging.error("Duty cycle must be between 0 and 100 percent")
        sys.exit(1)

    if args.display_time <= 0:
        logging.error("Display time must be greater than 0")
        sys.exit(1)

    try:
        display_price(args.price, args.gpio_pins, args.frequency, args.duty_cycle, args.display_time, args.simulate)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

