import time
import atexit
import logging
from board import SCL, SDA
import busio
from adafruit_pca9685 import PCA9685
from gpiozero import LED
from picamera2 import Picamera2

class Fuchikoma:
    def __init__(self):
        self.i2c = busio.I2C(SCL, SDA)
        try:
            self.pca = PCA9685(self.i2c)
            self.pca.frequency = 60
        except (ValueError, OSError) as e:
            logging.error("PCA9685 not found on I2C bus: %s", e)
            exit(1)

        self.servos = {
            'claw': 0,
            'lock': 1,
            'water_gun': 2
        }
        self.angle_to_pulse = lambda angle: int((angle + 77) / 154 * 65535)
        atexit.register(self.cleanup)

    def move_servo(self, servo_name, angle, delay=0.029):
        if servo_name not in self.servos:
            raise ValueError(f"Invalid servo name: {servo_name}")
        if not -77 <= angle <= 77:
            raise ValueError(f"Angle {angle} out of range (-77 to 77)")

        channel = self.servos[servo_name]
        pulse_width = self.angle_to_pulse(angle)
        self.pca.channels[channel].duty_cycle = pulse_width
        time.sleep(delay)
        self.pca.channels[channel].duty_cycle = 0

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75, delay=0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        for channel in self.pca.channels:
            channel.duty_cycle = 0
        self.i2c.deinit()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    robot = Fuchikoma()

    try:
        robot.bite()
        robot.open_claw()
        robot.lock()
        robot.unlock()
        robot.shoot()
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    finally:
        robot.cleanup()

