import signal
import sys
import time
import logging
from board import SCL, SDA
import busio
from adafruit_tcs34725 import TCS34725, IntegrationTime, Gain
from PIL import Image
from collections import Counter

# Configure logging
logging.basicConfig(level=logging.INFO)

# Initialize I2C bus
try:
    i2c = busio.I2C(SCL, SDA)
except Exception as e:
    logging.error(f"Failed to initialize I2C bus: {e}")
    sys.exit(1)

# Initialize TCS34725 sensor
try:
    sensor = TCS34725(i2c)
    sensor.integration_time = IntegrationTime.INTEGRATION_TIME_50MS
    sensor.gain = Gain.GAIN_4X
except Exception as e:
    logging.error(f"Failed to initialize TCS34725 sensor: {e}")
    i2c.deinit()
    sys.exit(1)

def get_sensor_color_data():
    try:
        r, g, b, c = sensor.color_rgb_bytes
        return (r, g, b, c)
    except Exception as e:
        logging.error(f"Failed to read sensor data: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            pixels = list(img.getdata())
            color_counts = Counter(pixels)
            dominant_color = color_counts.most_common(1)[0][0]
            return dominant_color
    except FileNotFoundError:
        logging.error(f"Image file not found: {image_path}")
        return (0, 0, 0)
    except Exception as e:
        logging.error(f"Failed to process image: {e}")
        return (0, 0, 0)

def signal_handler(sig, frame):
    logging.info("Shutting down...")
    i2c.deinit()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    try:
        while True:
            sensor_data = get_sensor_color_data()
            dominant_color = find_dominant_image_color('image.jpg')
            print(f"Sensor Color: R={sensor_data[0]}, G={sensor_data[1]}, B={sensor_data[2]}, Clear={sensor_data[3]}")
            print(f"Dominant Image Color: R={dominant_color[0]}, G={dominant_color[1]}, B={dominant_color[2]}")
            time.sleep(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        i2c.deinit()
        sys.exit(1)

if __name__ == "__main__":
    main()

