import socket
import json
import signal
import sys
import time
import logging
from threading import Thread
from gpiozero import LED
from picamera2 import Picamera2
from adafruit_gps import GPS
import serial
import smbus2

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
gps = None
tracking_state = False
gps_coordinates = {"lat": 0.0, "lon": 0.0}

def read_gps_position():
    global gps_coordinates
    try:
        if gps is not None:
            while not gps.has_fix:
                time.sleep(1)
            gps_coordinates = {"lat": gps.latitude, "lon": gps.longitude}
            logging.debug(f"GPS Coordinates: {gps_coordinates}")
        else:
            # Simulated GPS data
            gps_coordinates = {"lat": 37.7749, "lon": -122.4194}
            logging.debug(f"Simulated GPS Coordinates: {gps_coordinates}")
    except Exception as e:
        logging.error(f"Failed to read GPS position: {e}")
        gps_coordinates = {"lat": 0.0, "lon": 0.0}

def handle_command(command):
    global tracking_state
    try:
        if command == "start":
            tracking_state = True
            logging.info("Tracking started.")
            return "Tracking started."
        elif command == "stop":
            tracking_state = False
            logging.info("Tracking stopped.")
            return "Tracking stopped."
        elif command == "report":
            read_gps_position()
            return json.dumps(gps_coordinates)
        else:
            logging.warning(f"Invalid command: {command}")
            return "Invalid command."
    except Exception as e:
        logging.error(f"Error handling command: {e}")
        return "Error processing command."

def main():
    global gps
    try:
        # Initialize GPS via UART
        try:
            ser = serial.Serial("/dev/serial0", baudrate=9600, timeout=1)
            gps = GPS(ser, debug=False)
        except Exception as e:
            logging.error(f"Failed to initialize GPS via UART: {e}")
            try:
                # Fallback to I2C
                bus = smbus2.SMBus(1)
                gps = GPS(bus, address=0x42, debug=False)
            except Exception as e:
                logging.error(f"Failed to initialize GPS via I2C: {e}")
                gps = None

        # Set up socket
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.settimeout(2)
        server_socket.bind(("127.0.0.1", 9099))
        server_socket.listen(5)
        logging.info("Listening on 127.0.0.1:9099")

        def signal_handler(sig, frame):
            logging.info("Shutting down...")
            if gps is not None:
                gps.deinit()
            server_socket.close()
            sys.exit(0)

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        while True:
            try:
                client_socket, address = server_socket.accept()
                logging.info(f"Connection from {address}")
                command = client_socket.recv(1024).decode('utf-8').strip()
                response = handle_command(command)
                client_socket.sendall(response.encode('utf-8'))
                client_socket.close()
            except socket.timeout:
                logging.debug("Socket timeout, waiting for next connection.")
            except Exception as e:
                logging.error(f"Error accepting connection: {e}")

    except Exception as e:
        logging.critical(f"Critical error: {e}")
    finally:
        if gps is not None:
            gps.deinit()
        server_socket.close()

if __name__ == "__main__":
    main()

