        raise ValueError(f"Invalid GPIO pin number: {pin}")

def chirp(buzzer, frequency, duration):
    GPIO.output(buzzer, GPIO.HIGH)
    time.sleep(duration)
    GPIO.output(buzzer, GPIO.LOW)

def chirp_sequence(buzzer1, buzzer2, led1=None, led2=None):
    for _ in range(3):
        chirp(buzzer1, random.randint(20000, 25000), random.uniform(0.1, 0.5))
        time.sleep(0.1)
        chirp(buzzer2, random.randint(20000, 25000), random.uniform(0.1, 0.5))
        time.sleep(0.2)
    time.sleep(60)

def main():
    parser = argparse.ArgumentParser(description="Bird Deterrent System")
    parser.add_argument("--gpio_buzzer1", type=int, required=True, help="GPIO pin for buzzer 1")
    parser.add_argument("--gpio_buzzer2", type=int, required=True, help="GPIO pin for buzzer 2")
    parser.add_argument("--gpio_led1", type=int, help="GPIO pin for LED 1")
    parser.add_argument("--gpio_led2", type=int, help="GPIO pin for LED 2")
    parser.add_argument("--log_file", default="bird_deterrent.log", help="Log file path")
    args = parser.parse_args()

    try:
        setup_logging(args.log_file)
        for pin in [args.gpio_buzzer1, args.gpio_buzzer2, args.gpio_led1, args.gpio_led2]:
            if pin is not None:
                validate_pin(pin)

        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        buzzers = [args.gpio_buzzer1, args.gpio_buzzer2]
        leds = [args.gpio_led1, args.gpio_led2]

        for buzzer in buzzers:
            if buzzer is not None:
                GPIO.setup(buzzer, GPIO.OUT)

        for led in leds:
            if led is not None:
                GPIO.setup(led, GPIO.OUT)

        def signal_handler(sig, frame):
            logging.info("Exiting...")
            GPIO.cleanup()
            sys.exit(0)

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        while True:
            sensor_value = random.randint(0, 100)
            logging.info(f"Sensor value: {sensor_value}")

            if sensor_value > 70:
                logging.info("Activating chirp sequence")
                if args.gpio_led1 is not None:
