                if args.gpio_led1 is not None:
                    GPIO.output(args.gpio_led1, GPIO.LOW)
                if args.gpio_led2 is not None:
                    GPIO.output(args.gpio_led2, GPIO.LOW)
            else:
                logging.info("Sensor value too low, no chirp")

            time.sleep(1)

    except Exception as e:
        logging.error(f"An error occurred: {str(e)}")
        GPIO.cleanup()
        sys.exit(1)

