import smbus2
import time
import threading
import RPi.GPIO as GPIO
from gpiozero import PWMOutputDevice

# Constants
I2C_BUS = 1
MPU6050_ADDR = 0x68
POWER_MGMT_REG = 0x6B
GYRO_XOUT_H = 0x43
GYRO_YOUT_H = 0x45
GYRO_ZOUT_H = 0x47
GYRO_SCALE = 131.0
SAMPLE_RATE = 100  # Hz
TIME_STEP = 0.01  # seconds
LOG_INTERVAL = 1  # seconds

# GPIO setup
GPIO.setmode(GPIO.BCM)
motors = {
    'x': PWMOutputDevice(17, frequency=50, initial_value=0),
    'y': PWMOutputDevice(18, frequency=50, initial_value=0),
    'z': PWMOutputDevice(27, frequency=50, initial_value=0)
}

# MPU6050 setup
bus = smbus2.SMBus(I2C_BUS)
bus.write_byte_data(MPU6050_ADDR, POWER_MGMT_REG, 0)

# Proportional gains
kp = {'x': 1.0, 'y': 1.0, 'z': 1.0}

# Angle and velocity
angle = {'x': 0.0, 'y': 0.0, 'z': 0.0}
velocity = {'x': 0.0, 'y': 0.0, 'z': 0.0}

def read_raw_gyro(reg):
    high = bus.read_byte_data(MPU6050_ADDR, reg)
    low = bus.read_byte_data(MPU6050_ADDR, reg + 1)
    value = (high << 8) + low
    if value >= 0x8000:
        return value - 0x10000
    else:
        return value

def control_loop():
    global angle, velocity
    try:
        while True:
            for axis in ['x', 'y', 'z']:
                raw = read_raw_gyro(globals()[f'GYRO_{axis.upper()}OUT_H'])
                gyro = raw / GYRO_SCALE
                velocity[axis] += gyro * TIME_STEP
                angle[axis] += velocity[axis] * TIME_STEP

                output = kp[axis] * angle[axis]
                output = max(min(output, 100), -100)

                motors[axis].value = abs(output) / 100.0
                if output < 0:
                    motors[axis].pin.duty_cycle = -output
                else:
                    motors[axis].pin.duty_cycle = output

            time.sleep(TIME_STEP)
    except IOError:
        print("I2C Error: MPU6050 not found or bus error.")
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

def cleanup():
    for motor in motors.values():
        motor.value = 0
        motor.close()
    GPIO.cleanup()
    print("Cleanup complete.")

def input_thread():
    global kp
    try:
        while True:
            command = input().strip().lower()
            if command.startswith('xkp'):
                kp['x'] = float(command.split()[1])
            elif command.startswith('ykp'):
                kp['y'] = float(command.split()[1])
            elif command.startswith('zkp'):
                kp['z'] = float(command.split()[1])
            elif command == 'quit':
                raise KeyboardInterrupt
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    control_thread = threading.Thread(target=control_loop)
    input_thread = threading.Thread(target=input_thread)

    control_thread.start()
    input_thread.start()

    try:
        while control_thread.is_alive():
            control_thread.join(timeout=LOG_INTERVAL)
            with open('log.txt', 'a') as log_file:
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
                log_file.write(f"{timestamp} - X: {angle['x']:.2f}, Y: {angle['y']:.2f}, Z: {angle['z']:.2f}\n")
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        cleanup()
        control_thread.join()
        input_thread.join()

