import RPi.GPIO as GPIO
import time
from datetime import datetime

# Constants
PIR_PIN = 4
FEEDING_WINDOW_1 = (7, 8)  # 7:00 AM to 8:00 AM
FEEDING_WINDOW_2 = (18, 19)  # 6:00 PM to 7:00 PM
DEBOUNCE_TIME = 60  # 60 seconds

# Initialize variables
last_feeding_time = None

def is_feeding_time(now):
    """Check if the current time is within feeding windows."""
    hour = now.hour
    return (FEEDING_WINDOW_1[0] <= hour < FEEDING_WINDOW_1[1]) or (FEEDING_WINDOW_2[0] <= hour < FEEDING_WINDOW_2[1])

def log_event(message):
    """Log an event with a timestamp."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - {message}")

def main():
    global last_feeding_time
    try:
        # Set up GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

        log_event("PIR sensor monitoring started.")

        while True:
            if GPIO.input(PIR_PIN):
                now = datetime.now()
                log_event("Motion detected!")

                if is_feeding_time(now):
                    if last_feeding_time is None or (now - last_feeding_time).total_seconds() >= DEBOUNCE_TIME:
                        print(f"Feeding initiated at {now.strftime('%Y-%m-%d %H:%M:%S')}")
                        last_feeding_time = now
                    else:
                        print("Not feeding time or recently fed.")
                else:
                    print("Not feeding time or recently fed.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

import atexit
import signal
import logging
from adafruit_motorkit import MotorKit
from adafruit_motor import motor
import board
import busio

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DCMotorHATExtra(MotorKit):
    def __init__(self, i2c_address=0x60, frequency=60):
        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            super().__init__(i2c=self.i2c, address=i2c_address, frequency=frequency)
            self.pwm_frequency = frequency
            logger.info("DCMotorHATExtra initialized with I2C address 0x%02X and frequency %d Hz", i2c_address, frequency)
        except Exception as e:
            logger.error("Failed to initialize DCMotorHATExtra: %s", e)
            raise

    def set_pwm_freq(self, frequency):
        try:
            self.pwm_frequency = frequency
            self._pca.frequency = frequency
            logger.info("PWM frequency set to %d Hz", frequency)
        except Exception as e:
            logger.error("Failed to set PWM frequency: %s", e)

    def get_pwm_freq(self):
        return self.pwm_frequency

    def release_all(self):
        try:
            for m in [self.motor1, self.motor2, self.motor3, self.motor4]:
                m.throttle = 0
            logger.info("All motors released")
        except Exception as e:
            logger.error("Failed to release motors: %s", e)

atexit.register(DCMotorHATExtra.release_all)

def signal_handler(sig, frame):
    logger.info("Received signal %d, shutting down", sig)
    DCMotorHATExtra.release_all()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

class DCMotor:
    def __init__(self, hat, motor_number, pwm_freq=None, invert=False):
        if motor_number not in [1, 2, 3, 4]:
            raise ValueError("Motor number must be 1, 2, 3, or 4")
        self.hat = hat
        self.motor_number = motor_number
        self.pwm_freq = pwm_freq if pwm_freq is not None else hat.get_pwm_freq()
        self.invert = invert
        self.last_duty_cycle = None
        self.motor = getattr(hat, f'motor{motor_number}')
        logger.info("DCMotor %d initialized with PWM freq %d Hz and invert %s", motor_number, self.pwm_freq, self.invert)

    def set_dc(self, duty_cycle):
        try:
            duty_cycle = max(-255, min(255, duty_cycle))
            if duty_cycle == 0:
                self.stop()
            else:
                direction = motor.FORWARD if (duty_cycle > 0) ^ self.invert else motor.BACKWARD
                self.motor.throttle = duty_cycle / 255.0
                logger.info("Motor %d set to %d%% %s", self.motor_number, abs(duty_cycle), "forward" if direction == motor.FORWARD else "backward")
            self.last_duty_cycle = duty_cycle
        except Exception as e:
            logger.error("Failed to set DC for motor %d: %s", self.motor_number, e)

    def stop(self):
        try:
            self.motor.throttle = 0
            logger.info("Motor %d stopped", self.motor_number)
        except Exception as e:
            logger.error("Failed to stop motor %d: %s", self.motor_number, e)

    def close(self):
        try:
            self.stop()
            logger.info("Motor %d resources cleaned up", self.motor_number)
        except Exception as e:
            logger.error("Failed to close motor %d: %s", self.motor_number, e)

    def get_status(self):
        return {
            "motor_number": self.motor_number,
            "pwm_frequency": self.pwm_freq,
            "invert": self.invert,
            "last_duty_cycle": self.last_duty_cycle
        }

# Usage example
if __name__ == "__main__":
    try:
        hat = DCMotorHATExtra()
        motor1 = DCMotor(hat, 1)

        # Ramp motor forward
        for i in range(-255, 256, 51):
            motor1.set_dc(i)

        # Ramp motor backward
        for i in range(255, -256, -51):
            motor1.set_dc(i)

        motor1.stop()
        motor1.close()
    except Exception as e:
        logger.error("An error occurred: %s", e)
    finally:
        DCMotorHATExtra.release_all()

