import RPi.GPIO as GPIO
import time
import logging
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

class ServoController:
    def __init__(self, gpio_pin=18, frequency=50):
        self.gpio_pin = gpio_pin
        self.frequency = frequency
        self.duty_cycle_min = 2.5  # 0 degrees
        self.duty_cycle_max = 12.5  # 180 degrees
        self._setup()

    def _setup(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.gpio_pin, self.frequency)
            self.pwm.start(0)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            raise

    def _angle_to_duty_cycle(self, angle):
        return self.duty_cycle_min + (angle / 180.0) * (self.duty_cycle_max - self.duty_cycle_min)

    def move_to(self, angle):
        duty_cycle = self._angle_to_duty_cycle(angle)
        self.pwm.ChangeDutyCycle(duty_cycle)
        logging.info(f"Moved servo to {angle} degrees (Duty Cycle: {duty_cycle:.2f}%)")
        time.sleep(0.5)  # Pause for observation

    def stop(self):
        self.pwm.stop()
        GPIO.cleanup()
        logging.info("Servo stopped and GPIO cleaned up.")

def main(angles):
    servo = None
    try:
        servo = ServoController()
        for angle in angles:
            servo.move_to(angle)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if servo:
            servo.stop()

if __name__ == "__main__":
    angles_to_sweep = [0, 45, 90, 135, 180, 135, 90, 45, 0]
    main(angles_to_sweep)

