import serial
import signal
import logging
from pymodbus.client import ModbusSerialClient
from pymodbus.exceptions import ModbusIOException, ConnectionException
from pymodbus.constants import Defaults

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Register map
REGISTER_MAP = {
    'STATUS': {'R/W': 'R', 'Register': 0x3000, 'functioncode': 3, 'read_length': 1},
    'CONTROL': {
        'R/W': 'W',
        'Register': 0x3100,
        'functioncode': 6,
        'Value': {'Stop': 0x0006, 'Start': 0x000F}
    },
    'OPMODE': {
        'R/W': 'W',
        'Register': 0x3500,
        'functioncode': 6,
        'Value': {'Position': 1}
    },
    'VelocityFeedback': {'R/W': 'R', 'Register': 0x3B00, 'functioncode': 3, 'read_length': 2},
    'PositionFeedback': {'R/W': 'R', 'Register': 0x3700, 'functioncode': 3, 'read_length': 2},
    'PositionCommand': {'R/W': 'W', 'Register': 0x4000, 'functioncode': 16},
    'VelocityCommand': {'R/W': 'W', 'Register': 0x6F00, 'functioncode': 16}
}

class Servo:
    def __init__(self, port='/dev/serial0', baudrate=115200):
        self.client = ModbusSerialClient(method='rtu', port=port, baudrate=baudrate)
        self.client.connect()
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def cleanup(self, signum, frame):
        logger.info("Cleaning up resources...")
        self.client.close()
        exit(0)

    def read_register(self, register_name):
        reg_info = REGISTER_MAP.get(register_name)
        if not reg_info or reg_info['R/W'] != 'R':
            logger.error(f"Invalid or read-only register: {register_name}")
            return None

        try:
            rr = self.client.read_holding_registers(reg_info['Register'], reg_info['read_length'])
            if rr.isError():
                logger.error(f"Error reading register {register_name}: {rr}")
                return None
            return rr.registers
        except (ModbusIOException, ConnectionException) as e:
            logger.error(f"Exception reading register {register_name}: {e}")
            return None

    def write_register(self, register_name, value):
        reg_info = REGISTER_MAP.get(register_name)
        if not reg_info or reg_info['R/W'] != 'W':
            logger.error(f"Invalid or write-only register: {register_name}")
            return False

        try:
            if 'Value' in reg_info and isinstance(value, str):
                value = reg_info['Value'].get(value)
                if value is None:
                    logger.error(f"Invalid value for register {register_name}: {value}")
                    return False

            if reg_info['functioncode'] == 6:
                result = self.client.write_register(reg_info['Register'], value)
            elif reg_info['functioncode'] == 16:
                result = self.client.write_registers(reg_info['Register'], [value])
            else:
                logger.error(f"Unsupported function code for register {register_name}")
                return False

            if result.isError():
                logger.error(f"Error writing register {register_name}: {result}")
                return False
            return True
        except (ModbusIOException, ConnectionException) as e:
            logger.error(f"Exception writing register {register_name}: {e}")
            return False

# Example usage
if __name__ == "__main__":
    try:
        servo = Servo()
        servo.write_register('CONTROL', 'Start')
        servo.write_register('OPMODE', 'Position')
        velocity = servo.read_register('VelocityFeedback')
        position = servo.read_register('PositionFeedback')
        logger.info(f"Velocity: {velocity}, Position: {position}")
    except Exception as e:
        logger.warning(f"Failed to initialize servo: {e}")

