import time
import signal
import logging
import sys

try:
    import automationhat
except ImportError:
    logging.error("automationhat library not installed. Exiting.")
    sys.exit(0)

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GarageDoor:
    def __init__(self, state_pin):
        self.state_pin = state_pin
        self.relay = automationhat.relay.one
        self.relay.off()
        self.verify_automationhat()

    def verify_automationhat(self):
        try:
            # Attempt to read a value to verify hardware is connected
            _ = automationhat.input(self.state_pin).read()
        except Exception as e:
            logging.error(f"Failed to verify automationhat: {e}. Exiting.")
            sys.exit(0)

    @property
    def state(self):
        try:
            state = automationhat.input(self.state_pin).read()
            if state is None:
                raise ValueError("Unexpected None value from input read.")
            return state
        except Exception as e:
            logging.error(f"Error reading door state: {e}")
            return None

    def trigger(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
        except Exception as e:
            logging.error(f"Error triggering relay: {e}")

    def toggle_door(self):
        current_state = self.state
        if current_state is None:
            logging.error("Cannot determine door state. Aborting toggle.")
            return

        if current_state == 1:
            logging.info("Door is closed. Opening door.")
            self.trigger()
        elif current_state == 0:
            logging.info("Door is open. Closing door.")
            self.trigger()
        else:
            logging.error(f"Unexpected door state: {current_state}")

def signal_handler(sig, frame):
    logging.info("Received signal to terminate. Shutting down gracefully.")
    My_Garage.relay.off()
    sys.exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Instantiate the GarageDoor object
My_Garage = GarageDoor(state_pin=1)

# Main loop
try:
    while True:
        My_Garage.toggle_door()
        time.sleep(1)  # Check door state every second
except KeyboardInterrupt:
    logging.info("KeyboardInterrupt received. Shutting down gracefully.")
finally:
    My_Garage.relay.off()

