import serial
import minimalmodbus
import signal
import logging
import sys

class ModbusServoController:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.instrument = None
        self.serial_connection = None
        self.setup_logging()

    def setup_logging(self):
        logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

    def open_connection(self):
        try:
            self.serial_connection = serial.Serial(self.port, self.baudrate, timeout=1)
            self.instrument = minimalmodbus.Instrument(self.serial_connection, self.slave_address)
            self.instrument.serial.timeout = 1  # seconds
            logging.info("Serial connection opened successfully.")
        except (serial.SerialException, minimalmodbus.NoResponseError) as e:
            logging.error(f"Failed to open serial connection: {e}")
            sys.exit(0)

    def close_connection(self):
        if self.serial_connection and self.serial_connection.is_open:
            self.serial_connection.close()
            logging.info("Serial connection closed.")

    def set_operation_mode(self, mode):
        try:
            self.instrument.write_register(0x3500, mode)
            logging.info(f"Operation mode set to {mode}.")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to set operation mode: {e}")

    def write_position_command(self, value):
        try:
            self.instrument.write_register(0x4000, value)
            logging.info(f"Position command written: {value}.")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to write position command: {e}")

    def write_velocity_command(self, value):
        try:
            self.instrument.write_register(0x6F00, value)
            logging.info(f"Velocity command written: {value}.")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to write velocity command: {e}")

    def read_position_feedback(self):
        try:
            position = self.instrument.read_registers(0x3700, 2)
            logging.info(f"Position feedback read: {position}.")
            return position
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to read position feedback: {e}")
            return None

    def read_velocity_feedback(self):
        try:
            velocity = self.instrument.read_registers(0x3B00, 2)
            logging.info(f"Velocity feedback read: {velocity}.")
            return velocity
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to read velocity feedback: {e}")
            return None

    def start(self):
        try:
            self.instrument.write_register(0x3100, 0x000F)
            logging.info("Servo started.")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to start servo: {e}")

    def stop(self):
        try:
            self.instrument.write_register(0x3100, 0x0006)
            logging.info("Servo stopped.")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to stop servo: {e}")

    def read_status(self):
        try:
            status = self.instrument.read_register(0x3000)
            logging.info(f"Status read: {status}.")
            return status
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to read status: {e}")
            return None

def signal_handler(sig, frame):
    logging.info("Received signal to terminate, closing resources.")
    controller.close_connection()
    sys.exit(0)

if __name__ == '__main__':
    controller = ModbusServoController()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    controller.open_connection()
    controller.start()
    controller.write_position_command(1000)
    controller.read_position_feedback()
    controller.read_velocity_feedback()
    controller.stop()
