from adafruit_servokit import ServoKit
from gpiozero import LED
import time
import sys

# Constants
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4
METAL = 135
PLASTIC = 180
PAPER = 90

# Initialize the ServoKit
try:
    kit = ServoKit(channels=16, address=0x40, busnum=1)
except Exception as e:
    print(f"Error initializing ServoKit: {e}")
    sys.exit(1)

def move_servo(channel, target_angle, step_size=5, delay=0.04):
    if not (0 <= channel <= 15):
        raise ValueError("Channel must be between 0 and 15")
    if not (0 <= target_angle <= 180):
        raise ValueError("Angle must be between 0 and 180")

    current_angle = kit.servo[channel].angle if kit.servo[channel].angle is not None else 90
    step = step_size if target_angle > current_angle else -step_size

    while current_angle != target_angle:
        current_angle += step
        if (step > 0 and current_angle > target_angle) or (step < 0 and current_angle < target_angle):
            current_angle = target_angle
        kit.servo[channel].angle = current_angle
        time.sleep(delay)

def seek(angle):
    move_servo(SEEK, angle)

def deseek(angle):
    move_servo(SEEK, 90)

def drop(angle):
    move_servo(DROP, angle)

def pick(angle):
    move_servo(GRAB, angle)

def grab(angle):
    pick(angle)

def release(angle):
    pick(120)

def collect_object_steps(seek_angle):
    seek(seek_angle)
    grab(90)
    move_servo(BASE, 160)
    move_servo(BASE, 100)
    grab(90)

def drop_object_steps(drop_angle):
    drop(drop_angle)
    release(120)
    move_servo(DROP, 100)

def get_pos_x(x_center):
    return max(0, min(180, int((x_center / 320) * 180)))

def get_pos_y(y_center):
    return max(0, min(180, int((y_center / 320) * 180)))

def collect_object(x_center, y_center, drop_angle):
    try:
        base_angle = get_pos_x(x_center)
        seek_angle = get_pos_y(y_center)

        move_servo(BASE, base_angle)
        collect_object_steps(seek_angle)
        drop_object_steps(drop_angle)
        move_servo(BASE, 90)
        move_servo(SEEK, 90)
        move_servo(GRAB, 90)
        move_servo(DROP, 100)
    except Exception as e:
        print(f"Error during object collection: {e}")

def cleanup():
    for i in range(16):
        kit.servo[i].angle = None
    print("Cleanup complete.")

if __name__ == "__main__":
    try:
        # Example usage
        collect_object(160, 120, METAL)
    except KeyboardInterrupt:
        print("KeyboardInterrupt received.")
    finally:
        cleanup()

