import RPi.GPIO as GPIO
import time
from datetime import datetime, time as dt_time

# Constants
RELAY_PIN = 17
SUNRISE = dt_time(7, 0)
SUNSET = dt_time(19, 0)
CHECK_INTERVAL = 60  # seconds

def log_event(message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - {message}")

def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT)
        log_event("GPIO setup successful")
    except Exception as e:
        log_event(f"GPIO setup failed: {e}")
        raise

def cleanup_gpio():
    GPIO.cleanup()
    log_event("GPIO cleanup completed")

def control_door(current_time):
    if SUNRISE <= current_time < SUNSET:
        GPIO.output(RELAY_PIN, GPIO.LOW)
        log_event("Door opened")
    else:
        GPIO.output(RELAY_PIN, GPIO.HIGH)
        log_event("Door closed")
    time.sleep(1)

def main():
    setup_gpio()
    try:
        while True:
            current_time = datetime.now().time()
            control_door(current_time)
            time.sleep(CHECK_INTERVAL)
    except KeyboardInterrupt:
        log_event("Script interrupted by user")
    except Exception as e:
        log_event(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

import time
from gpiozero import LED
