from adafruit_servokit import ServoKit
import paho.mqtt.client as mqtt
import signal
import sys

# Mocking adafruit_servokit for testing
try:
    from unittest.mock import patch
except ImportError:
    patch = None

# Initialize the ServoKit
def initialize_servo_kit():
    try:
        if patch:
            with patch('adafruit_servokit.ServoKit') as MockServoKit:
                kit = MockServoKit(channels=16)
                return kit
        else:
            kit = ServoKit(channels=16, address=0x40)
            return kit
    except (OSError, ValueError) as e:
        print(f"Error initializing ServoKit: {e}")
        sys.exit(1)

# Move servo to a specific angle
def move_servo(kit, servo_num, target_angle):
    if not (0 <= servo_num <= 15):
        raise ValueError("Servo number must be between 0 and 15.")
    if not (0 <= target_angle <= 180):
        raise ValueError("Target angle must be between 0 and 180 degrees.")

    current_angle = kit.servo[servo_num].angle if kit.servo[servo_num].angle is not None else 0
    step = 5 if current_angle < target_angle else -5

    while current_angle != target_angle:
        current_angle += step
        if (step > 0 and current_angle > target_angle) or (step < 0 and current_angle < target_angle):
            current_angle = target_angle
        kit.servo[servo_num].angle = current_angle
        time.sleep(0.04)

# Grab object by moving servo to 90 degrees
def grab_object(kit, servo_num=0):
    move_servo(kit, servo_num, 90)

# Release object by moving servo to 150 degrees
def release_object(kit, servo_num=0):
    move_servo(kit, servo_num, 150)

# Clean up resources
def cleanup(kit, picam, client):
    if kit:
        for i in range(16):
            kit.servo[i].angle = None
    if picam:
        picam.stop()
    if client:
        client.disconnect()
    print("Resources cleaned up.")

# Signal handler for graceful exit
def signal_handler(sig, frame):
    print("KeyboardInterrupt received. Exiting...")
    cleanup(kit, picam, client)
    sys.exit(0)

# Main execution
if __name__ == "__main__":
    kit = initialize_servo_kit()
    picam = Picamera2()
    client = mqtt.Client()

    signal.signal(signal.SIGINT, signal_handler)

    try:
        picam.start()
        grab_object(kit)
        time.sleep(2)  # Simulate holding the object
        release_object(kit)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup(kit, picam, client)

