import smbus2
from datetime import datetime
import signal
import sys

class DS1338RTC:
    def __init__(self, bus_number=1, address=0x68):
        self.bus = smbus2.SMBus(bus_number)
        self.address = address
        self._verify_device()
        signal.signal(signal.SIGINT, self._cleanup)
        signal.signal(signal.SIGTERM, self._cleanup)

    def _verify_device(self):
        try:
            self.bus.read_byte(self.address)
        except OSError:
            raise RuntimeError("DS1338 RTC not found at address 0x{:02X}".format(self.address))

    def _bcd_to_int(self, bcd):
        return (bcd // 16) * 10 + (bcd % 16)

    def _int_to_bcd(self, integer):
        return (integer // 10) * 16 + (integer % 10)

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.address, reg)
        except OSError as e:
            raise RuntimeError("I2C read error: {}".format(e))

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.address, reg, value)
        except OSError as e:
            raise RuntimeError("I2C write error: {}".format(e))

    def read_seconds(self):
        return self._bcd_to_int(self._read_register(0x00) & 0x7F)

    def read_minutes(self):
        return self._bcd_to_int(self._read_register(0x01))

    def read_hours(self):
        hours = self._bcd_to_int(self._read_register(0x02) & 0x3F)
        return hours if not (self._read_register(0x02) & 0x40) else hours - 12

    def read_date(self):
        return self._bcd_to_int(self._read_register(0x04))

    def read_month(self):
        return self._bcd_to_int(self._read_register(0x05) & 0x1F)

    def read_year(self):
        return self._bcd_to_int(self._read_register(0x06))

    def write_seconds(self, seconds):
        if 0 <= seconds <= 59:
            self._write_register(0x00, self._int_to_bcd(seconds))
        else:
            raise ValueError("Seconds must be between 0 and 59")

    def write_minutes(self, minutes):
        if 0 <= minutes <= 59:
            self._write_register(0x01, self._int_to_bcd(minutes))
        else:
            raise ValueError("Minutes must be between 0 and 59")

    def write_hours(self, hours, is_24_hour=True):
        if is_24_hour:
            if 0 <= hours <= 23:
                self._write_register(0x02, self._int_to_bcd(hours))
            else:
                raise ValueError("Hours must be between 0 and 23")
        else:
            if 1 <= hours <= 12:
                self._write_register(0x02, self._int_to_bcd(hours) & 0x1F)
            else:
                raise ValueError("Hours must be between 1 and 12")

    def write_date(self, date):
        if 1 <= date <= 31:
            self._write_register(0x04, self._int_to_bcd(date))
        else:
            raise ValueError("Date must be between 1 and 31")

    def write_month(self, month):
        if 1 <= month <= 12:
            self._write_register(0x05, self._int_to_bcd(month))
        else:
            raise ValueError("Month must be between 1 and 12")

    def write_year(self, year):
        if 0 <= year <= 99:
            self._write_register(0x06, self._int_to_bcd(year))
        else:
            raise ValueError("Year must be between 0 and 99")

    def read_datetime(self, century=21):
        return datetime(
            century + self.read_year(),
            self.read_month(),
            self.read_date(),
            self.read_hours(),
            self.read_minutes(),
            self.read_seconds()
        )

    def write_all(self, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
        if seconds is not None:
            self.write_seconds(seconds)
        if minutes is not None:
            self.write_minutes(minutes)
        if hours is not None:
            self.write_hours(hours)
        if date is not None:
            self.write_date(date)
        if month is not None:
            self.write_month(month)
        if year is not None:
            self.write_year(year)

    def _cleanup(self, signum, frame):
        self.bus.close()
        sys.exit(0)

# Example usage:
# rtc = DS1338RTC()
# rtc.write_all(seconds=30, minutes=45, hours=14, date=15, month=8, year=23)
# print(rtc.read_datetime())

