class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial = None
        try:
            self.serial = serial.Serial(port, baud_rate, timeout=timeout)
        except serial.SerialException as e:
            print(f"Failed to open serial port {port}: {e}")
            self.serial = None

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        if not self.serial:
            return None
        try:
            self.serial.write(command.encode() + b'\r\n')
            response = self.serial.read_until(wait_for, timeout=timeout)
            return response
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT')
        return response == b'OK\r\n'

    def restart(self):
        self._send_command('AT+RST', timeout=5.0)
        time.sleep(2)  # Wait for reboot
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        response = self._send_command(f'AT+CWJAP="{ssid}","{password}"', timeout=10.0)
        return response == b'OK\r\n'

    def disconnect_wifi(self):
        response = self._send_command('AT+CWQAP')
        return response == b'OK\r\n'

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        match = re.search(b'STAIP,"([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)"', response)
        return match.group(1).decode() if match else None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if not self.connect_wifi(host, ''):
            return None
        ip = self.get_ip()
        if not ip:
            return None

        self._send_command(f'AT+CIPSTART="TCP","{ip}",{port}')
        self._send_command(f'AT+CIPSEND={len(method) + len(url) + 2}')
        request = f'{method} {url} HTTP/1.1\r\nHost: {host}\r\n'
        if headers:
            request += ''.join(f'{k}: {v}\r\n' for k, v in headers.items())
        request += '\r\n'
        if data:
            request += data

        self.serial.write(request.encode())
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        response = b''
        while time.time() - start_time < timeout:
            try:
                line = self.serial.readline()
                if line:
                    response += line
                    if b'CLOSED' in line:
                        break
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
        return response

    def close(self):
        if self.serial:
            self.serial.close()

def signal_handler(sig, frame):
    print('Terminating program and closing serial port...')
    controller.close()
    exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    controller = ESP8266Controller()
    if controller.serial:
        if controller.test_connection():
            print("ESP8266 module is connected and responsive.")
        else:
            print("Failed to connect to ESP8266 module.")
    else:
        print("No serial connection established.")

