import serial
import time
import re

def nmea_to_decimal_degrees(nmea_coord):
    """Convert NMEA format (ddmm.mmmm) to decimal degrees."""
    if nmea_coord:
        degrees = float(nmea_coord[:2])
        minutes = float(nmea_coord[2:])
        return degrees + minutes / 60
    return None

def parse_gprmc_sentence(sentence):
    """Parse a GPRMC NMEA sentence and extract latitude and longitude."""
    pattern = r'\$GPRMC,\d+\.\d+,A,(\d+\.\d+),([NS]),(\d+\.\d+),([EW]),'
    match = re.match(pattern, sentence)
    if match:
        lat, lat_dir, lon, lon_dir = match.groups()
        lat_decimal = nmea_to_decimal_degrees(lat)
        lon_decimal = nmea_to_decimal_degrees(lon)
        if lat_dir == 'S':
            lat_decimal = -lat_decimal
        if lon_dir == 'W':
            lon_decimal = -lon_decimal
        return lat_decimal, lon_decimal
    return None, None

def main():
    ser = None
    try:
        ser = serial.Serial('/dev/serial0', baudrate=9600, timeout=1)
        while True:
            try:
                line = ser.readline().decode('ascii', errors='replace').strip()
                if line.startswith('$GPRMC'):
                    lat, lon = parse_gprmc_sentence(line)
                    if lat is not None and lon is not None:
                        print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")
            except serial.SerialException as e:
                print(f"Serial error: {e}")
            time.sleep(1)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        if ser and ser.is_open:
            ser.close()

if __name__ == "__main__":
