import serial
import signal
import logging
from dataclasses import dataclass
from typing import Optional

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@dataclass
class GPSReadings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None

class GPSReader:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None

    def connect(self):
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to GPS on {self.port}")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self.serial_port = None

    def disconnect(self):
        if self.serial_port and self.serial_port.is_open:
            self.serial_port.close()
            logging.info(f"Disconnected from GPS on {self.port}")
        self.serial_port = None

    def read_gps_data(self):
        if not self.serial_port or not self.serial_port.is_open:
            logging.warning("GPS port is not open.")
            return None

        try:
            line = self.serial_port.readline().decode('ascii', errors='replace').strip()
            if not line.startswith('$GPGGA'):
                return None

            parts = line.split(',')
            if len(parts) < 15:
                logging.warning("Incomplete GPGGA sentence.")
                return None

            try:
                latitude = self._convert_to_decimal_degrees(parts[2], parts[3])
                longitude = self._convert_to_decimal_degrees(parts[4], parts[5])
                altitude = float(parts[9]) if parts[9] else None
                satellite_count = int(parts[7]) if parts[7] else None
            except ValueError as e:
                logging.error(f"Error parsing GPGGA data: {e}")
                return None

            return GPSReadings(latitude, longitude, altitude, satellite_count)
        except Exception as e:
            logging.error(f"Error reading GPS data: {e}")
            return None

    def _convert_to_decimal_degrees(self, value, direction):
        if not value:
            return None
        try:
            degrees = float(value[:2])
            minutes = float(value[2:])
            decimal_degrees = degrees + minutes / 60
            if direction in ['S', 'W']:
                decimal_degrees = -decimal_degrees
            return decimal_degrees
        except ValueError as e:
            logging.error(f"Error converting NMEA to decimal degrees: {e}")
            return None

def signal_handler(signum, frame):
    logging.info("Received signal to terminate. Cleaning up...")
    gps_reader.disconnect()
    exit(0)

