import serial
import signal
import time

class GPSController:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.serial = None
        try:
            self.serial = serial.Serial(port, baud, timeout=1)
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to open serial port {port}: {e}")

    def attach(self):
        try:
            self.serial.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            if self.serial.in_waiting == 0:
                raise RuntimeError("Failed to power on GNSS")
        except serial.SerialException as e:
            raise RuntimeError(f"Error while attaching GNSS: {e}")

    def detach(self):
        try:
            self.serial.write(b'AT+CGNSPWR=0\r\n')
            time.sleep(1)
            if self.serial.in_waiting == 0:
                raise RuntimeError("Failed to power off GNSS")
        except serial.SerialException as e:
            raise RuntimeError(f"Error while detaching GNSS: {e}")

    def get_data(self):
        try:
            if self.serial.in_waiting > 0:
                data = self.serial.readline().decode('ascii').strip()
                if data.startswith('$GPRMC'):
                    parts = data.split(',')
                    if len(parts) > 2 and parts[2] == 'A':
                        return parts
            return None
        except serial.SerialException as e:
            raise RuntimeError(f"Error while reading data: {e}")

    def close(self):
        if self.serial and self.serial.is_open:
            self.serial.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def signal_handler(sig, frame):
    print("Signal received, closing port...")
    gps_controller.close()
    exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GPSController() as gps_controller:
        gps_controller.attach()
        try:
            while True:
                data = gps_controller.get_data()
                if data:
                    print("Valid GPS Data:", data)
                time.sleep(1)
        except KeyboardInterrupt:
            pass
        finally:
            gps_controller.detach()

