import serial
import time

def main():
    try:
        # Open the serial port
        ser = serial.Serial('/dev/ttyUSB0', baudrate=9600, bytesize=serial.EIGHTBITS,
                            parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE,
                            timeout=1)
        print("Serial port opened successfully.")

        try:
            while True:
                # Read a line from the serial port
                line = ser.readline().decode('ascii', errors='replace').strip()

                if line:
                    try:
                        # Split the line into heart rate and SpO2
                        heart_rate, spo2 = line.split(',')
                        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")
                    except ValueError:
                        print(f"Warning: Invalid data format - {line}")

                # Delay between readings
                time.sleep(1)

        except KeyboardInterrupt:
            print("\nProgram interrupted by user.")

        finally:
            # Ensure the serial port is closed
            ser.close()
            print("Serial port closed.")

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")

if __name__ == "__main__":
    main()

