from flask import Flask, jsonify, request, abort, make_response
from gpiozero import LED
from picamera2 import Picamera2
import serial
import paho.mqtt.client as mqtt
import threading
import time
import json

app = Flask(__name__)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False}
]

# Serial port configuration
serial_port = '/dev/ttyUSB0'
baud_rate = 9600

# Function to open and interact with the serial port
def query_instrument():
    try:
        with serial.Serial(serial_port, baud_rate, timeout=1) as ser:
            ser.write(b'*IDN?\n')
            time.sleep(0.1)
            response = ser.read_all().decode('utf-8').replace('\n', '<br>')
            return response
    except serial.SerialException as e:
        return None, str(e)

@app.route('/version')
def version():
    response, error = query_instrument()
    if response is None:
        return make_response(f"Error: {error}", 503)
    return response, 200, {'Content-Type': 'text/html'}

@app.route('/getdata')
def get_data():
    return jsonify(data_store)

@app.route('/getset/<int:item_id>')
def get_set_item(item_id):
    item = next((item for item in data_store if item['id'] == item_id), None)
    if item is None:
        abort(404)
    return jsonify(item)

@app.route('/getpost/<int:item_id>/<name>')
def get_post_item(item_id, name):
    new_item = {"id": item_id, "name": name, "done": False}
    data_store.append(new_item)
    return jsonify(data_store)

@app.route('/postjson', methods=['POST'])
def post_json():
    if request.is_json:
        content = request.get_json()
    else:
        content = request.form.to_dict()

    try:
        new_id = max(item['id'] for item in data_store) + 1
        new_item = {
            "id": new_id,
            "name": content.get('name', ''),
            "done": content.get('done', False) in [True, 'true', 'True']
        }
        data_store.append(new_item)
        return jsonify(data_store)
    except (TypeError, ValueError) as e:
        abort(400, description="Invalid input data")

@app.route('/postjson', methods=['GET'])
def get_json():
    return jsonify(data_store)

@app.errorhandler(404)
def not_found(error):
    return make_response(jsonify({'error': 'Not found'}), 404)

@app.errorhandler(400)
def bad_request(error):
    return make_response(jsonify({'error': str(error.description)}), 400)

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000)
    except Exception as e:
        print(f"Error starting Flask app: {e}")
    finally:
        # Ensure all resources are released
        print("Shutting down...")

