import serial
import time

def send_command(serial_conn, command):
    try:
        formatted_command = f'X{command}\n'
        serial_conn.write(formatted_command.encode('utf-8'))
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command: {e}")

def main():
    try:
        serial_conn = serial.Serial('/dev/rfcomm4', baudrate=38400, timeout=1)
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")

    try:
        while True:
            command = input("Enter command (or 'exit' to quit): ")
            if command.lower() == 'exit':
                break
            send_command(serial_conn, command)
    except KeyboardInterrupt:
        print("\nExiting...")
    except RuntimeError as e:
        print(f"Error: {e}")
    finally:
        if 'serial_conn' in locals() and serial_conn.is_open:
            serial_conn.close()

if __name__ == "__main__":
    main()

